/**
 * Error hierarchy and source marks, mirroring PyYAML's `yaml/error.py`.
 *
 * `Mark` keeps a pointer into the code-point buffer so that error messages can
 * reproduce the offending line together with a caret, exactly like Python does.
 */

const LINE_BREAKS = ['\0', '\r', '\n', '\x85', ' ', ' '];

/** Repeat a space `n` times (n may be negative, which yields ''). */
function spaces(n) {
  return n > 0 ? ' '.repeat(n) : '';
}

export class Mark {
  /**
   * @param {string} name       stream name, e.g. "<unicode string>"
   * @param {number} index      code-point index in the stream
   * @param {number} line       zero based line number
   * @param {number} column     zero based column number
   * @param {string[]|null} buffer array of code points (may be null)
   * @param {number|null} pointer index into `buffer`
   */
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && !LINE_BREAKS.includes(this.buffer[start - 1])) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && !LINE_BREAKS.includes(this.buffer[end])) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
    }
    const snippet = this.buffer.slice(start, end).join('');
    return spaces(indent) + head + snippet + tail + '\n' +
      spaces(indent + this.pointer - start + head.length) + '^';
  }

  toString() {
    const snippet = this.getSnippet();
    let where = `  in "${this.name}", line ${this.line + 1}, column ${this.column + 1}`;
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

/** Base class of every error raised by this library. */
export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.name = 'yaml.error.YAMLError';
    this.pythonMessage = message;
  }

  /** Rendered like `str(exception)` in Python. */
  toString() {
    return this.pythonMessage;
  }
}

/** Error carrying context/problem marks (see PyYAML's MarkedYAMLError). */
export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super('');
    this.name = 'yaml.error.MarkedYAMLError';
    this.context = context === undefined ? null : context;
    this.contextMark = contextMark === undefined ? null : contextMark;
    this.problem = problem === undefined ? null : problem;
    this.problemMark = problemMark === undefined ? null : problemMark;
    this.note = note === undefined ? null : note;
    this.pythonMessage = this.render();
    this.message = this.pythonMessage;
  }

  render() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (this.contextMark !== null &&
        (this.problem === null || this.problemMark === null ||
         this.contextMark.name !== this.problemMark.name ||
         this.contextMark.line !== this.problemMark.line ||
         this.contextMark.column !== this.problemMark.column)) {
      lines.push(String(this.contextMark));
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(String(this.problemMark));
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }
}

/** Factory that keeps the Python dotted class name attached to each error. */
function marked(pythonName) {
  return class extends MarkedYAMLError {
    constructor(context, contextMark, problem, problemMark, note) {
      super(context, contextMark, problem, problemMark, note);
      this.name = pythonName;
    }
  };
}

function plain(pythonName) {
  return class extends YAMLError {
    constructor(message) {
      super(message);
      this.name = pythonName;
    }
  };
}

export const ReaderError = class extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super('');
    this.name = 'yaml.reader.ReaderError';
    this.streamName = name;
    this.position = position;
    this.character = character;
    this.encoding = encoding;
    this.reason = reason;
    this.pythonMessage = this.render();
    this.message = this.pythonMessage;
  }

  render() {
    // Only the "unicode" branch is reachable: this library reads strings.
    const hex = this.character.toString(16).padStart(2, '0');
    return `unacceptable character #x${hex}: ${this.reason}\n` +
      `  in "${this.streamName}", position ${this.position}`;
  }
};

export const ScannerError = marked('yaml.scanner.ScannerError');
export const ParserError = marked('yaml.parser.ParserError');
export const ComposerError = marked('yaml.composer.ComposerError');
export const ConstructorError = marked('yaml.constructor.ConstructorError');
export const EmitterError = plain('yaml.emitter.EmitterError');
export const SerializerError = plain('yaml.serializer.SerializerError');
export const RepresenterError = plain('yaml.representer.RepresenterError');

/** Raised where CPython would raise ValueError (invalid dates, bad base64…). */
export const PythonValueError = plain('ValueError');

