/**
 * Character classification helpers shared by the scanner, resolver and emitter.
 *
 * PyYAML expresses these tests as `ch in '...'` membership checks against short
 * string literals; the equivalents here keep the same names so the ported code
 * stays easy to compare against the original.
 */

export const NULL = '\0';
export const LS = ' ';
export const PS = ' ';
export const NEL = '\x85';

/** '\n\x85  ' — characters PyYAML treats as line breaks. */
export const BREAKS = '\n' + NEL + LS + PS;
/** '\r\n\x85  ' — line breaks including carriage return. */
export const FULL_BREAKS = '\r' + BREAKS;
/** '\0 \t\r\n\x85  ' — whitespace, breaks and the end sentinel. */
export const NULL_BL_T_LINEBR = NULL + ' \t' + FULL_BREAKS;
/** '\0\r\n\x85  ' */
export const NULL_OR_LINEBR = NULL + FULL_BREAKS;
/** ' \t' */
export const SPACE_TAB = ' \t';

export function isBreak(ch) {
  return BREAKS.indexOf(ch) !== -1 && ch !== '';
}

export function isFullBreak(ch) {
  return FULL_BREAKS.indexOf(ch) !== -1 && ch !== '';
}

export function inSet(ch, set) {
  return ch !== '' && set.indexOf(ch) !== -1;
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

export function isAlphaNumeric(ch) {
  // PyYAML's `ch in '0123456789ABCDEF...-_'` test used for anchors and tags.
  return (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') ||
    (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_';
}

/**
 * True for code points PyYAML's Reader accepts, i.e. everything outside
 * `[^\x09\x0A\x0D\x20-\x7E\x85\xA0-퟿-�\U00010000-\U0010FFFF]`.
 */
export function isPrintable(codePoint) {
  if (codePoint === 0x09 || codePoint === 0x0a || codePoint === 0x0d) return true;
  if (codePoint >= 0x20 && codePoint <= 0x7e) return true;
  if (codePoint === 0x85) return true;
  if (codePoint >= 0xa0 && codePoint <= 0xd7ff) return true;
  if (codePoint >= 0xe000 && codePoint <= 0xfffd) return true;
  if (codePoint >= 0x10000 && codePoint <= 0x10ffff) return true;
  return false;
}

/** Split a string into an array of code points (Python-style iteration). */
export function toCodePoints(text) {
  return Array.from(text);
}

/** Compare two strings by code point, the way Python orders `str`. */
export function compareCodePoints(a, b) {
  const left = Array.from(a);
  const right = Array.from(b);
  const n = Math.min(left.length, right.length);
  for (let i = 0; i < n; i += 1) {
    const x = left[i].codePointAt(0);
    const y = right[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  if (left.length === right.length) return 0;
  return left.length < right.length ? -1 : 1;
}

