/**
 * Character stream with line/column bookkeeping — port of PyYAML's Reader.
 *
 * The whole input is available up front (this library only reads strings), so
 * the buffer is simply an array of code points terminated by '\0'.
 */

import { Mark, ReaderError } from './errors.mjs';
import { isPrintable, toCodePoints, inSet, FULL_BREAKS } from './chars.mjs';

export class Reader {
  /**
   * @param {string} text  the document source
   * @param {string} name  stream name used in error messages
   */
  constructor(text, name = '<unicode string>') {
    this.name = name;
    this.checkPrintable(text);
    this.buffer = toCodePoints(text);
    this.buffer.push('\0');
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
  }

  checkPrintable(text) {
    let offset = 0;
    for (const ch of text) {
      const code = ch.codePointAt(0);
      if (!isPrintable(code)) {
        throw new ReaderError(this.name, offset, code, 'unicode',
          'special characters are not allowed');
      }
      offset += 1;
    }
  }

  /** The code point `index` positions ahead, or '\0' past the end. */
  peek(index = 0) {
    const ch = this.buffer[this.pointer + index];
    return ch === undefined ? '\0' : ch;
  }

  /** The next `length` code points as a string. */
  prefix(length = 1) {
    return this.buffer.slice(this.pointer, this.pointer + length).join('');
  }

  forward(length = 1) {
    let remaining = length;
    while (remaining > 0) {
      const ch = this.buffer[this.pointer];
      if (ch === undefined) break;
      this.pointer += 1;
      this.index += 1;
      if (inSet(ch, '\n\x85  ') ||
          (ch === '\r' && this.buffer[this.pointer] !== '\n')) {
        this.line += 1;
        this.column = 0;
      } else {
        this.column += 1;
      }
      remaining -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column, this.buffer, this.pointer);
  }
}

export { FULL_BREAKS };

