/**
 * Token types produced by the scanner (PyYAML's `yaml/tokens.py`).
 *
 * Each token records its start/end marks; `id` replaces Python's class identity
 * checks so the parser can switch on a plain string.
 */

export class Token {
  constructor(startMark, endMark) {
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

function tokenClass(id, extra = []) {
  const cls = class extends Token {
    constructor(...args) {
      const startMark = args[args.length - 2];
      const endMark = args[args.length - 1];
      super(startMark, endMark);
      extra.forEach((field, i) => { this[field] = args[i]; });
    }
  };
  Object.defineProperty(cls.prototype, 'id', { value: id });
  Object.defineProperty(cls, 'tokenId', { value: id });
  return cls;
}

export const DirectiveToken = tokenClass('<directive>', ['name', 'value']);
export const DocumentStartToken = tokenClass('<document start>');
export const DocumentEndToken = tokenClass('<document end>');
export const StreamStartToken = tokenClass('<stream start>', ['encoding']);
export const StreamEndToken = tokenClass('<stream end>');
export const BlockSequenceStartToken = tokenClass('<block sequence start>');
export const BlockMappingStartToken = tokenClass('<block mapping start>');
export const BlockEndToken = tokenClass('<block end>');
export const FlowSequenceStartToken = tokenClass('[');
export const FlowMappingStartToken = tokenClass('{');
export const FlowSequenceEndToken = tokenClass(']');
export const FlowMappingEndToken = tokenClass('}');
export const KeyToken = tokenClass('?');
export const ValueToken = tokenClass(':');
export const BlockEntryToken = tokenClass('-');
export const FlowEntryToken = tokenClass(',');
export const AliasToken = tokenClass('<alias>', ['value']);
export const AnchorToken = tokenClass('<anchor>', ['value']);
export const TagToken = tokenClass('<tag>', ['value']);
export const ScalarToken = class extends Token {
  constructor(value, plain, startMark, endMark, style = null) {
    super(startMark, endMark);
    this.value = value;
    this.plain = plain;
    this.style = style;
  }
};
Object.defineProperty(ScalarToken.prototype, 'id', { value: '<scalar>' });

/** StreamStartToken takes only an encoding, so re-declare with marks first. */
export function makeStreamStart(startMark, endMark, encoding = null) {
  const token = new StreamStartToken(encoding, startMark, endMark);
  return token;
}

