/**
 * Small helpers that reproduce Python built-in formatting used in messages.
 */

/** Python's `repr()` for a string value (used in scanner/parser messages). */
export function pyRepr(text) {
  const chars = Array.from(text);
  const hasSingle = chars.includes("'");
  const hasDouble = chars.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of chars) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f) out += '\\x' + code.toString(16).padStart(2, '0');
    else if (code < 0x7f) out += ch;
    else if (isPrintableUnicode(code)) out += ch;
    else if (code <= 0xff) out += '\\x' + code.toString(16).padStart(2, '0');
    else if (code <= 0xffff) out += '\\u' + code.toString(16).padStart(4, '0');
    else out += '\\U' + code.toString(16).padStart(8, '0');
  }
  return out + quote;
}

/**
 * Approximation of Python's `str.isprintable()` for code points above ASCII:
 * C1 controls, separators and unassigned-ish ranges are escaped by repr().
 */
function isPrintableUnicode(code) {
  if (code >= 0x80 && code <= 0xa0) return false;
  if (code === 0xad) return false;
  if (code >= 0x2000 && code <= 0x200f) return false;
  if (code >= 0x2028 && code <= 0x202f) return false;
  if (code >= 0x205f && code <= 0x206f) return false;
  if (code === 0xfeff) return false;
  return true;
}

/** Zero padded uppercase hex, like Python's '%02X'. */
export function hexUpper(code, width) {
  return code.toString(16).toUpperCase().padStart(width, '0');
}

