/**
 * Tokenizer — a port of PyYAML's `yaml/scanner.py`.
 *
 * The structure (fetch_*/scan_*/check_* families, simple-key bookkeeping and
 * indent stack) is kept one-to-one with the original so that both error
 * positions and accepted syntax match Python exactly.
 */

import { Reader } from './reader.mjs';
import { ScannerError } from './errors.mjs';
import { pyRepr } from './pyformat.mjs';
import { inSet, NULL_BL_T_LINEBR, NULL_OR_LINEBR, isDigit, isAlphaNumeric } from './chars.mjs';
import {
  DirectiveToken, DocumentStartToken, DocumentEndToken, StreamStartToken,
  StreamEndToken, BlockSequenceStartToken, BlockMappingStartToken, BlockEndToken,
  FlowSequenceStartToken, FlowMappingStartToken, FlowSequenceEndToken,
  FlowMappingEndToken, KeyToken, ValueToken, BlockEntryToken, FlowEntryToken,
  AliasToken, AnchorToken, TagToken, ScalarToken,
} from './tokens.mjs';

/** '\0 \r\n\x85' + LS + PS — used where tabs are not allowed. */
const NULL_BL_LINEBR = '\0 \r\n\x85  ';
/** Breaks plus '\0', without spaces. */
const BREAK_OR_NULL = NULL_OR_LINEBR;

const ESCAPE_REPLACEMENTS = new Map([
  ['0', '\0'], ['a', '\x07'], ['b', '\x08'], ['t', '\x09'], ['\t', '\x09'],
  ['n', '\x0A'], ['v', '\x0B'], ['f', '\x0C'], ['r', '\x0D'], ['e', '\x1B'],
  [' ', '\x20'], ['"', '"'], ['\\', '\\'], ['N', '\x85'], ['_', '\xA0'],
  [' ', ' '], ['L', ' '], ['P', ' '],
]);

const ESCAPE_CODES = new Map([['x', 2], ['u', 4], ['U', 8]]);

const HEX_DIGITS = '0123456789ABCDEFabcdef';

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

export class Scanner {
  constructor(text, name = '<unicode string>') {
    this.reader = new Reader(text, name);
    this.encoding = null;

    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.fetchStreamStart();
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    this.possibleSimpleKeys = new Map();
  }

  // --- Reader delegation -------------------------------------------------

  get line() { return this.reader.line; }

  get column() { return this.reader.column; }

  get index() { return this.reader.index; }

  peek(index = 0) { return this.reader.peek(index); }

  prefix(length = 1) { return this.reader.prefix(length); }

  forward(length = 1) { this.reader.forward(length); }

  getMark() { return this.reader.getMark(); }

  // --- Public token API --------------------------------------------------

  /** True when the next token's id is one of `ids` (or any token exists). */
  checkToken(...ids) {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length > 0) {
      if (ids.length === 0) return true;
      return ids.includes(this.tokens[0].id);
    }
    return false;
  }

  peekToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    return this.tokens.length > 0 ? this.tokens[0] : null;
  }

  getToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length > 0) {
      this.tokensTaken += 1;
      return this.tokens.shift();
    }
    return null;
  }

  needMoreTokens() {
    if (this.done) return false;
    if (this.tokens.length === 0) return true;
    // The current token may be a potential simple key, look further.
    this.stalePossibleSimpleKeys();
    return this.nextPossibleSimpleKey() === this.tokensTaken;
  }

  fetchMoreTokens() {
    this.scanToNextToken();
    this.stalePossibleSimpleKeys();
    this.unwindIndent(this.column);

    const ch = this.peek();

    if (ch === '\0') return this.fetchStreamEnd();
    if (ch === '%' && this.checkDirective()) return this.fetchDirective();
    if (ch === '-' && this.checkDocumentStart()) return this.fetchDocumentStart();
    if (ch === '.' && this.checkDocumentEnd()) return this.fetchDocumentEnd();
    if (ch === '[') return this.fetchFlowSequenceStart();
    if (ch === '{') return this.fetchFlowMappingStart();
    if (ch === ']') return this.fetchFlowSequenceEnd();
    if (ch === '}') return this.fetchFlowMappingEnd();
    if (ch === ',') return this.fetchFlowEntry();
    if (ch === '-' && this.checkBlockEntry()) return this.fetchBlockEntry();
    if (ch === '?' && this.checkKey()) return this.fetchKey();
    if (ch === ':' && this.checkValue()) return this.fetchValue();
    if (ch === '*') return this.fetchAlias();
    if (ch === '&') return this.fetchAnchor();
    if (ch === '!') return this.fetchTag();
    if (ch === '|' && !this.flowLevel) return this.fetchLiteral();
    if (ch === '>' && !this.flowLevel) return this.fetchFolded();
    if (ch === "'") return this.fetchSingle();
    if (ch === '"') return this.fetchDouble();
    if (this.checkPlain()) return this.fetchPlain();

    throw new ScannerError('while scanning for the next token', null,
      `found character ${pyRepr(ch)} that cannot start any token`, this.getMark());
  }

  // --- Simple keys -------------------------------------------------------

  nextPossibleSimpleKey() {
    let minTokenNumber = null;
    for (const key of this.possibleSimpleKeys.values()) {
      if (minTokenNumber === null || key.tokenNumber < minTokenNumber) {
        minTokenNumber = key.tokenNumber;
      }
    }
    return minTokenNumber;
  }

  stalePossibleSimpleKeys() {
    for (const level of Array.from(this.possibleSimpleKeys.keys())) {
      const key = this.possibleSimpleKeys.get(level);
      if (key.line !== this.line || this.index - key.index > 1024) {
        if (key.required) {
          throw new ScannerError('while scanning a simple key', key.mark,
            "could not find expected ':'", this.getMark());
        }
        this.possibleSimpleKeys.delete(level);
      }
    }
  }

  savePossibleSimpleKey() {
    const required = !this.flowLevel && this.indent === this.column;
    if (this.allowSimpleKey) {
      this.removePossibleSimpleKey();
      const tokenNumber = this.tokensTaken + this.tokens.length;
      const key = new SimpleKey(tokenNumber, required, this.index, this.line,
        this.column, this.getMark());
      this.possibleSimpleKeys.set(this.flowLevel, key);
    }
  }

  removePossibleSimpleKey() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      if (key.required) {
        throw new ScannerError('while scanning a simple key', key.mark,
          "could not find expected ':'", this.getMark());
      }
      this.possibleSimpleKeys.delete(this.flowLevel);
    }
  }

  // --- Indentation -------------------------------------------------------

  unwindIndent(column) {
    if (this.flowLevel) return;
    while (this.indent > column) {
      const mark = this.getMark();
      this.indent = this.indents.pop();
      this.tokens.push(new BlockEndToken(mark, mark));
    }
  }

  addIndent(column) {
    if (this.indent < column) {
      this.indents.push(this.indent);
      this.indent = column;
      return true;
    }
    return false;
  }

  // --- Fetchers ----------------------------------------------------------

  fetchStreamStart() {
    const mark = this.getMark();
    this.tokens.push(new StreamStartToken(this.encoding, mark, mark));
  }

  fetchStreamEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.possibleSimpleKeys = new Map();
    const mark = this.getMark();
    this.tokens.push(new StreamEndToken(mark, mark));
    this.done = true;
  }

  fetchDirective() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanDirective());
  }

  fetchDocumentStart() {
    this.fetchDocumentIndicator(DocumentStartToken);
  }

  fetchDocumentEnd() {
    this.fetchDocumentIndicator(DocumentEndToken);
  }

  fetchDocumentIndicator(TokenClass) {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward(3);
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
  }

  fetchFlowSequenceStart() {
    this.fetchFlowCollectionStart(FlowSequenceStartToken);
  }

  fetchFlowMappingStart() {
    this.fetchFlowCollectionStart(FlowMappingStartToken);
  }

  fetchFlowCollectionStart(TokenClass) {
    this.savePossibleSimpleKey();
    this.flowLevel += 1;
    this.allowSimpleKey = true;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
  }

  fetchFlowSequenceEnd() {
    this.fetchFlowCollectionEnd(FlowSequenceEndToken);
  }

  fetchFlowMappingEnd() {
    this.fetchFlowCollectionEnd(FlowMappingEndToken);
  }

  fetchFlowCollectionEnd(TokenClass) {
    this.removePossibleSimpleKey();
    this.flowLevel -= 1;
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
  }

  fetchFlowEntry() {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new FlowEntryToken(startMark, endMark));
  }

  fetchBlockEntry() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null, 'sequence entries are not allowed here',
          this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new BlockSequenceStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new BlockEntryToken(startMark, endMark));
  }

  fetchKey() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null, 'mapping keys are not allowed here',
          this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new BlockMappingStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = !this.flowLevel;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new KeyToken(startMark, endMark));
  }

  fetchValue() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      this.possibleSimpleKeys.delete(this.flowLevel);
      this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
        new KeyToken(key.mark, key.mark));
      if (!this.flowLevel) {
        if (this.addIndent(key.column)) {
          this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
            new BlockMappingStartToken(key.mark, key.mark));
        }
      }
      this.allowSimpleKey = false;
    } else {
      if (!this.flowLevel) {
        if (!this.allowSimpleKey) {
          throw new ScannerError(null, null, 'mapping values are not allowed here',
            this.getMark());
        }
      }
      if (!this.flowLevel) {
        if (this.addIndent(this.column)) {
          const mark = this.getMark();
          this.tokens.push(new BlockMappingStartToken(mark, mark));
        }
      }
      this.allowSimpleKey = !this.flowLevel;
      this.removePossibleSimpleKey();
    }
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new ValueToken(startMark, endMark));
  }

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AliasToken));
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AnchorToken));
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanTag());
  }

  fetchLiteral() {
    this.fetchBlockScalar('|');
  }

  fetchFolded() {
    this.fetchBlockScalar('>');
  }

  fetchBlockScalar(style) {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    this.tokens.push(this.scanBlockScalar(style));
  }

  fetchSingle() {
    this.fetchFlowScalar("'");
  }

  fetchDouble() {
    this.fetchFlowScalar('"');
  }

  fetchFlowScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanFlowScalar(style));
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanPlain());
  }

  // --- Checkers ----------------------------------------------------------

  checkDirective() {
    return this.column === 0;
  }

  checkDocumentStart() {
    return this.column === 0 && this.prefix(3) === '---' &&
      inSet(this.peek(3), NULL_BL_T_LINEBR);
  }

  checkDocumentEnd() {
    return this.column === 0 && this.prefix(3) === '...' &&
      inSet(this.peek(3), NULL_BL_T_LINEBR);
  }

  checkBlockEntry() {
    return inSet(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkKey() {
    if (this.flowLevel) return true;
    return inSet(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkValue() {
    if (this.flowLevel) return true;
    return inSet(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkPlain() {
    const ch = this.peek();
    return !inSet(ch, NULL_BL_T_LINEBR + '-?:,[]{}#&*!|>\'"%@`') ||
      (!inSet(this.peek(1), NULL_BL_T_LINEBR) &&
        (ch === '-' || (!this.flowLevel && inSet(ch, '?:'))));
  }

  // --- Scanners ----------------------------------------------------------

  scanToNextToken() {
    if (this.index === 0 && this.peek() === '﻿') this.forward();
    let found = false;
    while (!found) {
      while (this.peek() === ' ') this.forward();
      if (this.peek() === '#') {
        while (!inSet(this.peek(), BREAK_OR_NULL)) this.forward();
      }
      if (this.scanLineBreak()) {
        if (!this.flowLevel) this.allowSimpleKey = true;
      } else {
        found = true;
      }
    }
  }

  scanDirective() {
    const startMark = this.getMark();
    this.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    let endMark;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
      endMark = this.getMark();
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
      endMark = this.getMark();
    } else {
      endMark = this.getMark();
      while (!inSet(this.peek(), BREAK_OR_NULL)) this.forward();
    }
    this.scanDirectiveIgnoredLine(startMark);
    return new DirectiveToken(name, value, startMark, endMark);
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.peek(length);
    while (isAlphaNumeric(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`, this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!inSet(ch, NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`, this.getMark());
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const major = this.scanYamlDirectiveNumber(startMark);
    if (this.peek() !== '.') {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit or '.', but found ${pyRepr(this.peek())}`, this.getMark());
    }
    this.forward();
    const minor = this.scanYamlDirectiveNumber(startMark);
    if (!inSet(this.peek(), NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit or ' ', but found ${pyRepr(this.peek())}`, this.getMark());
    }
    return [major, minor];
  }

  scanYamlDirectiveNumber(startMark) {
    const ch = this.peek();
    if (!isDigit(ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit, but found ${pyRepr(ch)}`, this.getMark());
    }
    let length = 0;
    while (isDigit(this.peek(length))) length += 1;
    const value = Number.parseInt(this.prefix(length), 10);
    this.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const handle = this.scanTagDirectiveHandle(startMark);
    while (this.peek() === ' ') this.forward();
    const prefix = this.scanTagDirectivePrefix(startMark);
    return [handle, prefix];
  }

  scanTagDirectiveHandle(startMark) {
    const value = this.scanTagHandle('directive', startMark);
    const ch = this.peek();
    if (ch !== ' ') {
      throw new ScannerError('while scanning a directive', startMark,
        `expected ' ', but found ${pyRepr(ch)}`, this.getMark());
    }
    return value;
  }

  scanTagDirectivePrefix(startMark) {
    const value = this.scanTagUri('directive', startMark);
    const ch = this.peek();
    if (!inSet(ch, NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected ' ', but found ${pyRepr(ch)}`, this.getMark());
    }
    return value;
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!inSet(this.peek(), BREAK_OR_NULL)) this.forward();
    }
    const ch = this.peek();
    if (!inSet(ch, BREAK_OR_NULL)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a comment or a line break, but found ${pyRepr(ch)}`, this.getMark());
    }
    this.scanLineBreak();
  }

  scanAnchor(TokenClass) {
    const startMark = this.getMark();
    const indicator = this.peek();
    const name = indicator === '*' ? 'alias' : 'anchor';
    this.forward();
    let length = 0;
    let ch = this.peek(length);
    while (isAlphaNumeric(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError(`while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`, this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!inSet(ch, NULL_BL_T_LINEBR + '?:,]}%@`')) {
      throw new ScannerError(`while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`, this.getMark());
    }
    const endMark = this.getMark();
    return new TokenClass(value, startMark, endMark);
  }

  scanTag() {
    const startMark = this.getMark();
    let ch = this.peek(1);
    let handle = null;
    let suffix;
    if (ch === '<') {
      handle = null;
      this.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.peek() !== '>') {
        throw new ScannerError('while parsing a tag', startMark,
          `expected '>', but found ${pyRepr(this.peek())}`, this.getMark());
      }
      this.forward();
    } else if (inSet(ch, NULL_BL_T_LINEBR)) {
      handle = null;
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!inSet(ch, NULL_BL_LINEBR)) {
        if (ch === '!') {
          useHandle = true;
          break;
        }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!inSet(ch, NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a tag', startMark,
        `expected ' ', but found ${pyRepr(ch)}`, this.getMark());
    }
    const value = [handle, suffix];
    const endMark = this.getMark();
    return new TagToken(value, startMark, endMark);
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    const chunks = [];
    const startMark = this.getMark();
    this.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);

    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let indent;
    let breaks;
    let endMark;
    if (increment === null) {
      const result = this.scanBlockScalarIndentation();
      breaks = result[0];
      const maxIndent = result[1];
      endMark = result[2];
      indent = Math.max(minIndent, maxIndent);
    } else {
      indent = minIndent + increment - 1;
      const result = this.scanBlockScalarBreaks(indent);
      breaks = result[0];
      endMark = result[1];
    }
    let lineBreak = '';

    while (this.column === indent && this.peek() !== '\0') {
      chunks.push(...breaks);
      const leadingNonSpace = !inSet(this.peek(), ' \t');
      let length = 0;
      while (!inSet(this.peek(length), BREAK_OR_NULL)) length += 1;
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      const result = this.scanBlockScalarBreaks(indent);
      breaks = result[0];
      endMark = result[1];
      if (this.column === indent && this.peek() !== '\0') {
        if (folded && lineBreak === '\n' && leadingNonSpace && !inSet(this.peek(), ' \t')) {
          if (breaks.length === 0) chunks.push(' ');
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }

    if (chomping !== false) chunks.push(lineBreak);
    if (chomping === true) chunks.push(...breaks);

    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (inSet(ch, '+-')) {
      chomping = ch === '+';
      this.forward();
      ch = this.peek();
      if (isDigit(ch)) {
        increment = Number.parseInt(ch, 10);
        if (increment === 0) {
          throw new ScannerError('while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0', this.getMark());
        }
        this.forward();
      }
    } else if (isDigit(ch)) {
      increment = Number.parseInt(ch, 10);
      if (increment === 0) {
        throw new ScannerError('while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0', this.getMark());
      }
      this.forward();
      ch = this.peek();
      if (inSet(ch, '+-')) {
        chomping = ch === '+';
        this.forward();
      }
    }
    ch = this.peek();
    if (!inSet(ch, NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected chomping or indentation indicators, but found ${pyRepr(ch)}`, this.getMark());
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!inSet(this.peek(), BREAK_OR_NULL)) this.forward();
    }
    const ch = this.peek();
    if (!inSet(ch, BREAK_OR_NULL)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected a comment or a line break, but found ${pyRepr(ch)}`, this.getMark());
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (inSet(this.peek(), ' \r\n\x85  ')) {
      if (this.peek() !== ' ') {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) maxIndent = this.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === ' ') this.forward();
    while (inSet(this.peek(), '\r\n\x85  ')) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === ' ') this.forward();
    }
    return [chunks, endMark];
  }

  scanFlowScalar(style) {
    const double = style === '"';
    const chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    while (this.peek() !== quote) {
      chunks.push(...this.scanFlowScalarSpaces(double, startMark));
      chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    }
    this.forward();
    const endMark = this.getMark();
    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    for (;;) {
      let length = 0;
      while (!inSet(this.peek(length), '\'"\\' + NULL_BL_T_LINEBR)) length += 1;
      if (length) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      let ch = this.peek();
      if (!double && ch === "'" && this.peek(1) === "'") {
        chunks.push("'");
        this.forward(2);
      } else if ((double && ch === "'") || (!double && inSet(ch, '"\\'))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === '\\') {
        this.forward();
        ch = this.peek();
        if (ESCAPE_REPLACEMENTS.has(ch)) {
          chunks.push(ESCAPE_REPLACEMENTS.get(ch));
          this.forward();
        } else if (ESCAPE_CODES.has(ch)) {
          length = ESCAPE_CODES.get(ch);
          this.forward();
          for (let k = 0; k < length; k += 1) {
            if (!inSet(this.peek(k), HEX_DIGITS)) {
              throw new ScannerError('while scanning a double-quoted scalar', startMark,
                `expected escape sequence of ${length} hexdecimal numbers, but found ` +
                `${pyRepr(this.peek(k))}`, this.getMark());
            }
          }
          const code = Number.parseInt(this.prefix(length), 16);
          chunks.push(String.fromCodePoint(code));
          this.forward(length);
        } else if (inSet(ch, '\r\n\x85  ')) {
          this.scanLineBreak();
          chunks.push(...this.scanFlowScalarBreaks(double, startMark));
        } else {
          throw new ScannerError('while scanning a double-quoted scalar', startMark,
            `found unknown escape character ${pyRepr(ch)}`, this.getMark());
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (inSet(this.peek(length), ' \t')) length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === '\0') {
      throw new ScannerError('while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark());
    } else if (inSet(ch, '\r\n\x85  ')) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (breaks.length === 0) chunks.push(' ');
      chunks.push(...breaks);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    for (;;) {
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && inSet(this.peek(3), NULL_BL_T_LINEBR)) {
        throw new ScannerError('while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.getMark());
      }
      while (inSet(this.peek(), ' \t')) this.forward();
      if (inSet(this.peek(), '\r\n\x85  ')) {
        chunks.push(this.scanLineBreak());
      } else {
        return chunks;
      }
    }
  }

  scanPlain() {
    const chunks = [];
    const startMark = this.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    let spaces = [];
    for (;;) {
      let length = 0;
      if (this.peek() === '#') break;
      for (;;) {
        const ch = this.peek(length);
        if (inSet(ch, NULL_BL_T_LINEBR) ||
            (ch === ':' && inSet(this.peek(length + 1),
              NULL_BL_T_LINEBR + (this.flowLevel ? ',[]{}' : ''))) ||
            (this.flowLevel && inSet(ch, ',?[]{}'))) {
          break;
        }
        length += 1;
      }
      if (length === 0) break;
      this.allowSimpleKey = false;
      chunks.push(...spaces);
      chunks.push(this.prefix(length));
      this.forward(length);
      endMark = this.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (spaces === null || spaces.length === 0 || this.peek() === '#' ||
          (!this.flowLevel && this.column < indent)) {
        break;
      }
    }
    return new ScalarToken(chunks.join(''), true, startMark, endMark);
  }

  scanPlainSpaces() {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ') length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (inSet(ch, '\r\n\x85  ')) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      let prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && inSet(this.peek(3), NULL_BL_T_LINEBR)) {
        return null;
      }
      const breaks = [];
      while (inSet(this.peek(), ' \r\n\x85  ')) {
        if (this.peek() === ' ') {
          this.forward();
        } else {
          breaks.push(this.scanLineBreak());
          prefix = this.prefix(3);
          if ((prefix === '---' || prefix === '...') && inSet(this.peek(3), NULL_BL_T_LINEBR)) {
            return null;
          }
        }
      }
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (breaks.length === 0) chunks.push(' ');
      chunks.push(...breaks);
    } else if (whitespaces) {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanTagHandle(name, startMark) {
    let ch = this.peek();
    if (ch !== '!') {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        `expected '!', but found ${pyRepr(ch)}`, this.getMark());
    }
    let length = 1;
    ch = this.peek(length);
    if (ch !== ' ') {
      while (isAlphaNumeric(ch)) {
        length += 1;
        ch = this.peek(length);
      }
      if (ch !== '!') {
        this.forward(length);
        throw new ScannerError(`while scanning a ${name}`, startMark,
          `expected '!', but found ${pyRepr(ch)}`, this.getMark());
      }
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while (isAlphaNumeric(ch) || inSet(ch, ";/?:@&=+$,.!~*'()[]%")) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (chunks.length === 0) {
      throw new ScannerError(`while parsing a ${name}`, startMark,
        `expected URI, but found ${pyRepr(ch)}`, this.getMark());
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const codes = [];
    const mark = this.getMark();
    while (this.peek() === '%') {
      this.forward();
      for (let k = 0; k < 2; k += 1) {
        if (!inSet(this.peek(k), HEX_DIGITS)) {
          throw new ScannerError(`while scanning a ${name}`, startMark,
            'expected URI escape sequence of 2 hexdecimal numbers, but found ' +
            `${pyRepr(this.peek(k))}`, this.getMark());
        }
      }
      codes.push(Number.parseInt(this.prefix(2), 16));
      this.forward(2);
    }
    const decoder = new TextDecoder('utf-8', { fatal: true });
    try {
      return decoder.decode(new Uint8Array(codes));
    } catch (err) {
      throw new ScannerError(`while scanning a ${name}`, startMark, String(err.message), mark);
    }
  }

  scanLineBreak() {
    const ch = this.peek();
    if (inSet(ch, '\r\n\x85')) {
      if (this.prefix(2) === '\r\n') this.forward(2);
      else this.forward();
      return '\n';
    }
    if (inSet(ch, '  ')) {
      this.forward();
      return ch;
    }
    return '';
  }
}

