input.content:
import fs from 'node:fs';

const path = process.argv[2];
const s = fs.readFileSync(path, 'utf8');
const lines = s.split('\n');
lines.forEach((l, i) => {
  const cps = Array.from(l).map((c) => c.codePointAt(0));
  if (cps.some((c) => c === 0x2028 || c === 0x2029 || (c > 0x7f))) {
    const shown = Array.from(l).map((c) => {
      const n = c.codePointAt(0);
      if (n === 0x2028) return '<LS>';
      if (n === 0x2029) return '<PS>';
      if (n > 0x7f) return '<U+' + n.toString(16) + '>';
      return c;
    }).join('');
    console.log((i + 1) + ': ' + shown);
  }
});

