import fs from 'node:fs';

const LS = ' ';
const PS = ' ';
const path = '/output/lib/scanner.mjs';
let s = fs.readFileSync(path, 'utf8');

const before = `  ['${LS}', '${LS}'], ['L', '${LS}'], ['P', '${PS}'],`;
const after = `  ['L', LS], ['P', PS],`;
if (!s.includes(before)) {
  console.error('pattern not found');
  process.exit(1);
}
s = s.replace(before, after);

// Import LS/PS from the shared character module.
s = s.replace(
  "import { inSet, NULL_BL_T_LINEBR, NULL_OR_LINEBR, isDigit, isAlphaNumeric } from './chars.mjs';",
  "import {\n  inSet, NULL_BL_T_LINEBR, NULL_OR_LINEBR, FULL_BREAKS, isDigit, isAlphaNumeric, LS, PS,\n} from './chars.mjs';",
);

// Replace inline break sets with the named constants.
s = s.split(`' \\r\\n\\x85${LS}${PS}'`).join("' ' + FULL_BREAKS");
s = s.split(`'\\r\\n\\x85${LS}${PS}'`).join('FULL_BREAKS');
s = s.split(`'${LS}${PS}'`).join('LS + PS');
s = s.replace(`const NULL_BL_LINEBR = '\\0 \\r\\n\\x85${LS}${PS}';`,
  "const NULL_BL_LINEBR = '\\0 ' + FULL_BREAKS;");

fs.writeFileSync(path, s);
console.log('patched');

