/**
 * Parse events (PyYAML's `yaml/events.py`).
 *
 * Instances expose an `id` string instead of relying on class identity, which
 * keeps the parser/emitter dispatch close to the Python `isinstance` checks.
 */

export class Event {
  constructor(startMark = null, endMark = null) {
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

export class NodeEvent extends Event {
  constructor(anchor, startMark, endMark) {
    super(startMark, endMark);
    this.anchor = anchor;
  }
}

export class CollectionStartEvent extends NodeEvent {
  constructor(anchor, tag, implicit, startMark, endMark, flowStyle = null) {
    super(anchor, startMark, endMark);
    this.tag = tag;
    this.implicit = implicit;
    this.flowStyle = flowStyle;
  }
}

export class CollectionEndEvent extends Event {}

export class StreamStartEvent extends Event {
  constructor(startMark = null, endMark = null, encoding = null) {
    super(startMark, endMark);
    this.encoding = encoding;
  }
}

export class StreamEndEvent extends Event {}

export class DocumentStartEvent extends Event {
  constructor(startMark = null, endMark = null, explicit = null, version = null, tags = null) {
    super(startMark, endMark);
    this.explicit = explicit;
    this.version = version;
    this.tags = tags;
  }
}

export class DocumentEndEvent extends Event {
  constructor(startMark = null, endMark = null, explicit = null) {
    super(startMark, endMark);
    this.explicit = explicit;
  }
}

export class AliasEvent extends NodeEvent {}

export class ScalarEvent extends NodeEvent {
  constructor(anchor, tag, implicit, value, startMark = null, endMark = null, style = null) {
    super(anchor, startMark, endMark);
    this.tag = tag;
    this.implicit = implicit;
    this.value = value;
    this.style = style;
  }
}

export class SequenceStartEvent extends CollectionStartEvent {}

export class SequenceEndEvent extends CollectionEndEvent {}

export class MappingStartEvent extends CollectionStartEvent {}

export class MappingEndEvent extends CollectionEndEvent {}

const IDS = [
  [StreamStartEvent, 'stream-start'], [StreamEndEvent, 'stream-end'],
  [DocumentStartEvent, 'document-start'], [DocumentEndEvent, 'document-end'],
  [AliasEvent, 'alias'], [ScalarEvent, 'scalar'],
  [SequenceStartEvent, 'sequence-start'], [SequenceEndEvent, 'sequence-end'],
  [MappingStartEvent, 'mapping-start'], [MappingEndEvent, 'mapping-end'],
];

for (const [cls, id] of IDS) {
  Object.defineProperty(cls.prototype, 'id', { value: id });
}

/** True when `event` is a scalar or a collection start (PyYAML's NodeEvent). */
export function isNodeEvent(event) {
  return event instanceof NodeEvent;
}

export function isCollectionStart(event) {
  return event instanceof CollectionStartEvent;
}

