/**
 * Event producer — a port of PyYAML's `yaml/parser.py`.
 *
 * The state machine, the states/marks stacks and every error message are kept
 * identical to the Python implementation.
 */

import { Scanner } from './scanner.mjs';
import { ParserError } from './errors.mjs';
import { pyRepr } from './pyformat.mjs';
import {
  StreamStartEvent, StreamEndEvent, DocumentStartEvent, DocumentEndEvent,
  AliasEvent, ScalarEvent, SequenceStartEvent, SequenceEndEvent,
  MappingStartEvent, MappingEndEvent,
} from './events.mjs';

const DEFAULT_TAGS = new Map([['!', '!'], ['!!', 'tag:yaml.org,2002:']]);

export class Parser extends Scanner {
  constructor(text, name = '<unicode string>') {
    super(text, name);
    this.currentEvent = null;
    this.yamlVersion = null;
    this.tagHandles = new Map();
    this.states = [];
    this.marks = [];
    this.state = this.parseStreamStart;
  }

  // --- Public event API --------------------------------------------------

  /** True when the next event's id is one of `ids` (or any event exists). */
  checkEvent(...ids) {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state.call(this);
    }
    if (this.currentEvent !== null) {
      if (ids.length === 0) return true;
      return ids.includes(this.currentEvent.id);
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state.call(this);
    }
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state.call(this);
    }
    const value = this.currentEvent;
    this.currentEvent = null;
    return value;
  }

  // --- Document structure ------------------------------------------------

  parseStreamStart() {
    const token = this.getToken();
    const event = new StreamStartEvent(token.startMark, token.endMark, token.encoding);
    this.state = this.parseImplicitDocumentStart;
    return event;
  }

  parseImplicitDocumentStart() {
    if (!this.checkToken('<directive>', '<document start>', '<stream end>')) {
      this.tagHandles = new Map(DEFAULT_TAGS);
      const token = this.peekToken();
      const startMark = token.startMark;
      const event = new DocumentStartEvent(startMark, startMark, false);
      this.states.push(this.parseDocumentEnd);
      this.state = this.parseBlockNode;
      return event;
    }
    return this.parseDocumentStart();
  }

  parseDocumentStart() {
    while (this.checkToken('<document end>')) this.getToken();
    let event;
    if (!this.checkToken('<stream end>')) {
      let token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken('<document start>')) {
        throw new ParserError(null, null,
          `expected '<document start>', but found ${pyRepr(this.peekToken().id)}`,
          this.peekToken().startMark);
