/**
 * Python-flavoured value types.
 *
 * The loader must round-trip Python semantics through the dumper, so integers
 * are `bigint` (arbitrary precision, like Python's int), floats are `number`,
 * and the container/date/bytes types below carry just enough behaviour to be
 * hashed as dict keys, compared for sorting and formatted like Python.
 */

import { PythonValueError } from './errors.mjs';
import { compareCodePoints } from './chars.mjs';

/** Python's `datetime.date`. */
export class PyDate {
  constructor(year, month, day) {
    checkDate(year, month, day);
    this.year = year;
    this.month = month;
    this.day = day;
  }

  /** `date.isoformat()` */
  isoformat() {
    return `${pad(this.year, 4)}-${pad(this.month, 2)}-${pad(this.day, 2)}`;
  }
}

/** Python's `datetime.datetime`, optionally carrying a fixed UTC offset. */
export class PyDateTime {
  constructor(year, month, day, hour = 0, minute = 0, second = 0, microsecond = 0,
    tzOffsetMinutes = null) {
    checkDate(year, month, day);
    if (hour < 0 || hour > 23) throw new PythonValueError('hour must be in 0..23');
    if (minute < 0 || minute > 59) throw new PythonValueError('minute must be in 0..59');
    if (second < 0 || second > 59) throw new PythonValueError('second must be in 0..59');
    if (microsecond < 0 || microsecond > 999999) {
      throw new PythonValueError('microsecond must be in 0..999999');
    }
    this.year = year;
    this.month = month;
    this.day = day;
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.tzOffsetMinutes = tzOffsetMinutes;
  }

  /** `datetime.isoformat(sep)` */
  isoformat(sep = 'T') {
    let out = `${pad(this.year, 4)}-${pad(this.month, 2)}-${pad(this.day, 2)}${sep}` +
      `${pad(this.hour, 2)}:${pad(this.minute, 2)}:${pad(this.second, 2)}`;
