/**
 * Implicit tag resolution — a port of PyYAML's `yaml/resolver.py`.
 *
 * Resolvers are indexed by the first character of the scalar and tried in
 * registration order, exactly as PyYAML does, so ambiguous values such as
 * "1:30" (int, not float) resolve the same way.
 */

import { SCALAR, SEQUENCE, MAPPING } from './nodes.mjs';
import {
  matchBool, matchFloat, matchInt, matchMerge, matchNull, matchTimestamp,
  matchValue, matchYaml,
} from './plainmatch.mjs';

export const DEFAULT_SCALAR_TAG = 'tag:yaml.org,2002:str';
export const DEFAULT_SEQUENCE_TAG = 'tag:yaml.org,2002:seq';
export const DEFAULT_MAPPING_TAG = 'tag:yaml.org,2002:map';

const DIGITS = '0123456789';

/** [tag, matcher, first characters] in PyYAML's registration order. */
const IMPLICIT_RESOLVERS = [
  ['tag:yaml.org,2002:bool', matchBool, 'yYnNtTfFoO'],
  ['tag:yaml.org,2002:float', matchFloat, '-+' + DIGITS + '.'],
  ['tag:yaml.org,2002:int', matchInt, '-+' + DIGITS],
  ['tag:yaml.org,2002:merge', matchMerge, '<'],
  ['tag:yaml.org,2002:null', matchNull, '~nN\0'],
  ['tag:yaml.org,2002:timestamp', matchTimestamp, DIGITS],
  ['tag:yaml.org,2002:value', matchValue, '='],
  ['tag:yaml.org,2002:yaml', matchYaml, '!&*'],
];

/** first character -> [[tag, matcher], …]; '' holds the empty-value entry. */
const BY_FIRST_CHAR = new Map();

for (const [tag, matcher, firstChars] of IMPLICIT_RESOLVERS) {
  for (const ch of firstChars) {
    const key = ch === '\0' ? '' : ch;
    if (!BY_FIRST_CHAR.has(key)) BY_FIRST_CHAR.set(key, []);
    BY_FIRST_CHAR.get(key).push([tag, matcher]);
  }
}

/**
 * Python's `$` also matches immediately before a single trailing newline, which
 * makes e.g. "123\n" resolve as an int. Keep that behaviour.
 */
function matchesAnchored(matcher, value) {
  if (matcher(value)) return true;
  if (value.endsWith('\n')) return matcher(value.slice(0, -1));
  return false;
}

export class Resolver {
  /**
   * @param {string} kind    one of SCALAR/SEQUENCE/MAPPING
   * @param {string|null} value  scalar contents
   * @param {boolean|boolean[]} implicit  [plainImplicit, quotedImplicit] for scalars
   */
  resolve(kind, value, implicit) {
    if (kind === SCALAR && implicit[0]) {
      const resolvers = BY_FIRST_CHAR.get(value === '' ? '' : value[0]) || [];
      for (const [tag, matcher] of resolvers) {
        if (matchesAnchored(matcher, value)) return tag;
      }
    }
    if (kind === SCALAR) return DEFAULT_SCALAR_TAG;
    if (kind === SEQUENCE) return DEFAULT_SEQUENCE_TAG;
    if (kind === MAPPING) return DEFAULT_MAPPING_TAG;
    return null;
  }

  /** Path resolvers are unused; these hooks exist to mirror the Python API. */
  descendResolver() {}

  ascendResolver() {}
}

