      ['tag:yaml.org,2002:omap', this.constructYamlOmap],
      ['tag:yaml.org,2002:pairs', this.constructYamlPairs],
      ['tag:yaml.org,2002:set', this.constructYamlSet],
      ['tag:yaml.org,2002:str', this.constructYamlStr],
      ['tag:yaml.org,2002:seq', this.constructYamlSeq],
      ['tag:yaml.org,2002:map', this.constructYamlMap],
    ]);
  }

  // --- Driver ------------------------------------------------------------

  getSingleData() {
    const node = this.getSingleNode();
    if (node !== null) return this.constructDocument(node);
    return null;
  }

  constructDocument(node) {
    const data = this.constructObject(node);
    while (this.stateGenerators.length > 0) {
      const generators = this.stateGenerators;
      this.stateGenerators = [];
      for (const generator of generators) {
        // Drain: the remainder of each constructor fills its container.
        while (!generator.next().done) { /* keep going */ }
      }
    }
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.deepConstruct = false;
    return data;
  }

  constructObject(node, deep = false) {
    if (this.constructedObjects.has(node)) return this.constructedObjects.get(node);
    let oldDeep = false;
    if (deep) {
      oldDeep = this.deepConstruct;
      this.deepConstruct = true;
    }
    if (this.recursiveObjects.has(node)) {
      throw new ConstructorError(null, null, 'found unconstructable recursive node',
        node.startMark);
    }
    this.recursiveObjects.set(node, null);
    const constructor = this.constructors.get(node.tag);
    let data;
    if (constructor === undefined) {
      data = this.constructUndefined(node);
    } else {
      data = constructor.call(this, node);
    }
    if (isGenerator(data)) {
      const generator = data;
      data = generator.next().value;
      if (this.deepConstruct) {
        while (!generator.next().done) { /* drain */ }
      } else {
        this.stateGenerators.push(generator);
      }
    }
    this.constructedObjects.set(node, data);
    this.recursiveObjects.delete(node);
    if (deep) this.deepConstruct = oldDeep;
    return data;
  }

  // --- Generic constructors ----------------------------------------------

  constructScalar(node) {
    if (node instanceof MappingNode) {
      for (const [keyNode, valueNode] of node.value) {
        if (keyNode.tag === 'tag:yaml.org,2002:value') return this.constructScalar(valueNode);
      }
    }
    if (!(node instanceof ScalarNode)) {
      throw new ConstructorError(null, null, `expected a scalar node, but found ${node.id}`,
        node.startMark);
    }
    return node.value;
  }

  constructSequence(node, deep = false) {
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError(null, null, `expected a sequence node, but found ${node.id}`,
        node.startMark);
    }
    return node.value.map((child) => this.constructObject(child, deep));
  }

  constructMapping(node, deep = false) {
    if (node instanceof MappingNode) this.flattenMapping(node);
    if (!(node instanceof MappingNode)) {
      throw new ConstructorError(null, null, `expected a mapping node, but found ${node.id}`,
        node.startMark);
    }
    const mapping = new PyDict();
    for (const [keyNode, valueNode] of node.value) {
      const key = this.constructObject(keyNode, deep);
      if (hashKey(key) === null) {
        throw new ConstructorError('while constructing a mapping', node.startMark,
          'found unhashable key', keyNode.startMark);
      }
      const value = this.constructObject(valueNode, deep);
      mapping.set(key, value);
    }
    return mapping;
  }

  flattenMapping(node) {
    let merge = [];
    let index = 0;
    while (index < node.value.length) {
      const [keyNode, valueNode] = node.value[index];
      if (keyNode.tag === 'tag:yaml.org,2002:merge') {
        node.value.splice(index, 1);
        if (valueNode instanceof MappingNode) {
          this.flattenMapping(valueNode);
          merge = merge.concat(valueNode.value);
        } else if (valueNode instanceof SequenceNode) {
          const submerge = [];
          for (const subnode of valueNode.value) {
            if (!(subnode instanceof MappingNode)) {
              throw new ConstructorError('while constructing a mapping', node.startMark,
                `expected a mapping for merging, but found ${subnode.id}`, subnode.startMark);
            }
            this.flattenMapping(subnode);
            submerge.push(subnode.value);
          }
          submerge.reverse();
          for (const value of submerge) merge = merge.concat(value);
        } else {
          throw new ConstructorError('while constructing a mapping', node.startMark,
            'expected a mapping or list of mappings for merging, but found ' +
            `${valueNode.id}`, valueNode.startMark);
        }
      } else if (keyNode.tag === 'tag:yaml.org,2002:value') {
        keyNode.tag = 'tag:yaml.org,2002:str';
        index += 1;
      } else {
        index += 1;
      }
    }
    if (merge.length > 0) node.value = merge.concat(node.value);
  }

  // --- Tag specific constructors -----------------------------------------

  constructYamlNull(node) {
    this.constructScalar(node);
    return null;
  }

  constructYamlBool(node) {
    const value = this.constructScalar(node);
    const key = value.toLowerCase();
    if (!BOOL_VALUES.has(key)) {
      throw new ConstructorError(null, null, `could not determine a boolean value from ` +
        `${pyRepr(value)}`, node.startMark);
    }
    return BOOL_VALUES.get(key);
  }

  constructYamlInt(node) {
    let value = this.constructScalar(node).split('_').join('');
    let sign = 1n;
    if (value[0] === '-') sign = -1n;
    if (value[0] === '+' || value[0] === '-') value = value.slice(1);
    if (value === '0') return 0n;
    if (value.startsWith('0b')) return sign * BigInt('0b' + value.slice(2));
    if (value.startsWith('0x')) return sign * BigInt('0x' + value.slice(2));
    if (value[0] === '0') return sign * BigInt('0o' + value.slice(1));
    if (value.includes(':')) {
      const digits = value.split(':').map((part) => BigInt(part));
      digits.reverse();
      let base = 1n;
      let total = 0n;
      for (const digit of digits) {
        total += digit * base;
        base *= 60n;
      }
      return sign * total;
    }
    return sign * BigInt(value);
  }

  constructYamlFloat(node) {
    let value = this.constructScalar(node).split('_').join('').toLowerCase();
    let sign = 1;
    if (value[0] === '-') sign = -1;
    if (value[0] === '+' || value[0] === '-') value = value.slice(1);
    if (value === '.inf') return sign * Infinity;
    if (value === '.nan') return NaN;
    if (value.includes(':')) {
      const digits = value.split(':').map((part) => Number(part));
      digits.reverse();
      let base = 1;
      let total = 0.0;
      for (const digit of digits) {
        total += digit * base;
        base *= 60;
      }
      return sign * total;
    }
    return sign * Number(value);
  }

  constructYamlBinary(node) {
    const value = this.constructScalar(node);
    for (const ch of value) {
      if (ch.codePointAt(0) > 0x7f) {
        throw new ConstructorError(null, null,
          'failed to convert base64 data into ascii: ' +
          `'ascii' codec can't encode character ${pyRepr(ch)}`, node.startMark);
      }
    }
    return new PyBytes(decodeBase64(value, node));
  }

  constructYamlTimestamp(node) {
    this.constructScalar(node);
    const fields = parseTimestamp(node.value);
    const year = Number.parseInt(fields.year, 10);
    const month = Number.parseInt(fields.month, 10);
    const day = Number.parseInt(fields.day, 10);
    if (!fields.hour) return new PyDate(year, month, day);
    const hour = Number.parseInt(fields.hour, 10);
    const minute = Number.parseInt(fields.minute, 10);
    const second = Number.parseInt(fields.second, 10);
    let fraction = 0;
    let tzOffsetMinutes = null;
    if (fields.fraction) {
      let digits = fields.fraction.slice(0, 6);
      while (digits.length < 6) digits += '0';
      fraction = Number.parseInt(digits, 10);
      if (fields.fraction.length > 6 && Number.parseInt(fields.fraction[6], 10) > 4) {
        fraction += 1;
      }
    }
    if (fields.tzSign) {
      const tzHour = Number.parseInt(fields.tzHour, 10);
      const tzMinute = fields.tzMinute ? Number.parseInt(fields.tzMinute, 10) : 0;
      let delta = tzHour * 60 + tzMinute;
      if (fields.tzSign === '-') delta = -delta;
      tzOffsetMinutes = delta;
    } else if (fields.tz) {
      tzOffsetMinutes = 0;
    }
    return new PyDateTime(year, month, day, hour, minute, second, fraction, tzOffsetMinutes);
  }

  * constructYamlOmap(node) {
    const omap = [];
    yield omap;
    this.fillPairs(node, omap, 'an ordered map');
  }

  * constructYamlPairs(node) {
    const pairs = [];
    yield pairs;
    this.fillPairs(node, pairs, 'pairs');
  }

  fillPairs(node, target, what) {
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError(`while constructing ${what}`, node.startMark,
        `expected a sequence, but found ${node.id}`, node.startMark);
    }
    for (const subnode of node.value) {
      if (!(subnode instanceof MappingNode)) {
        throw new ConstructorError(`while constructing ${what}`, node.startMark,
          `expected a mapping of length 1, but found ${subnode.id}`, subnode.startMark);
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError(`while constructing ${what}`, node.startMark,
          `expected a single mapping item, but found ${subnode.value.length} items`,
          subnode.startMark);
      }
      const [keyNode, valueNode] = subnode.value[0];
      const key = this.constructObject(keyNode);
      const value = this.constructObject(valueNode);
      target.push(new PyTuple([key, value]));
    }
  }

  * constructYamlSet(node) {
    const data = new PySet();
    yield data;
    const value = this.constructMapping(node);
    for (const [key] of value.items()) data.add(key);
  }

  constructYamlStr(node) {
    return this.constructScalar(node);
  }

  * constructYamlSeq(node) {
    const data = [];
    yield data;
    data.push(...this.constructSequence(node));
  }

  * constructYamlMap(node) {
    const data = new PyDict();
    yield data;
    const value = this.constructMapping(node);
    for (const [key, item] of value.items()) data.set(key, item);
  }

  constructUndefined(node) {
    throw new ConstructorError(null, null,
      `could not determine a constructor for the tag ${pyRepr(node.tag)}`, node.startMark);
  }
}

