/**
 * Python `repr()` for floats, plus the small numeric helpers the representer
 * needs. CPython prints the shortest round-tripping digit string and switches
 * to exponential notation when the decimal point lands outside (-4, 16].
 */

/** `repr(float)` for a finite, non-NaN double. */
export function floatRepr(value) {
  const negative = value < 0 || (value === 0 && 1 / value < 0);
  const magnitude = Math.abs(value);
  const [digits, exponent] = shortestDigits(magnitude);
  const decpt = exponent + 1;
  let out;
  if (decpt <= -4 || decpt > 16) {
    // Exponential form: d[.ddd]e±XX
    let mantissa = digits[0];
    if (digits.length > 1) mantissa += '.' + digits.slice(1);
    const expSign = exponent < 0 ? '-' : '+';
    const expDigits = String(Math.abs(exponent)).padStart(2, '0');
    out = `${mantissa}e${expSign}${expDigits}`;
  } else if (decpt <= 0) {
    out = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    out = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return negative ? '-' + out : out;
}

/**
 * Shortest digit string that round-trips, with its base-10 exponent, i.e.
 * value === 0.digits * 10 ** (exponent + 1).
 */
function shortestDigits(magnitude) {
  if (magnitude === 0) return ['0', 0];
  const text = magnitude.toExponential(); // "d[.ddd]e±X"
  const eIndex = text.indexOf('e');
  const mantissa = text.slice(0, eIndex);
  const exponent = Number.parseInt(text.slice(eIndex + 1), 10);
  const digits = mantissa.split('.').join('');
  return [digits, exponent];
}

