/**
 * Event → text writer — a port of PyYAML's `yaml/emitter.py`.
 *
 * This module decides every byte of the output: scalar style selection, line
 * folding at column 80, indentation and the `...` produced by an open ended
 * root scalar. It is intentionally a literal translation, including PyYAML's
 * quirks (such as the look-ahead in `analyzeScalar`).
 */

import { EmitterError } from './errors.mjs';
import { pyRepr, hexUpper } from './pyformat.mjs';
import { inSet, BREAKS, NULL_BL_T_LINEBR, LS, PS } from './chars.mjs';
import { isNodeEvent, isCollectionStart } from './events.mjs';

const DEFAULT_TAG_PREFIXES = new Map([
  ['!', '!'],
  ['tag:yaml.org,2002:', '!!'],
]);

/** ' \n\x85' + LS + PS — whitespace that matters for block hints. */
const SPACE_AND_BREAKS = ' ' + BREAKS;

const ESCAPE_REPLACEMENTS = new Map([
  ['\0', '0'], ['\x07', 'a'], ['\x08', 'b'], ['\x09', 't'], ['\x0A', 'n'],
  ['\x0B', 'v'], ['\x0C', 'f'], ['\x0D', 'r'], ['\x1B', 'e'], ['"', '"'],
  ['\\', '\\'], ['\x85', 'N'], ['\xA0', '_'], [LS, 'L'], [PS, 'P'],
]);

class ScalarAnalysis {
  constructor(scalar, empty, multiline, allowFlowPlain, allowBlockPlain,
    allowSingleQuoted, allowDoubleQuoted, allowBlock) {
    this.scalar = scalar;
    this.empty = empty;
    this.multiline = multiline;
    this.allowFlowPlain = allowFlowPlain;
    this.allowBlockPlain = allowBlockPlain;
    this.allowSingleQuoted = allowSingleQuoted;
    this.allowDoubleQuoted = allowDoubleQuoted;
    this.allowBlock = allowBlock;
  }
}

export class Emitter {
  /**
   * @param {{write: function(string): void}} stream sink for the generated text
   */
  constructor(stream, options = {}) {
    this.stream = stream;
    this.encoding = null;

    this.states = [];
    this.state = this.expectStreamStart;

    this.events = [];
    this.event = null;

    this.indents = [];
    this.indent = null;

    this.flowLevel = 0;
    this.rootContext = false;
    this.sequenceContext = false;
    this.mappingContext = false;
    this.simpleKeyContext = false;

    this.line = 0;
    this.column = 0;
    this.whitespace = true;
    this.indention = true;
    this.openEnded = false;

    this.canonical = options.canonical || null;
    this.allowUnicode = options.allowUnicode || null;

    this.bestIndent = 2;
    if (options.indent && options.indent > 1 && options.indent < 10) {
      this.bestIndent = options.indent;
    }
    this.bestWidth = 80;
    if (options.width && options.width > this.bestIndent * 2) {
      this.bestWidth = options.width;
    }
    this.bestLineBreak = '\n';
    if (options.lineBreak === '\r' || options.lineBreak === '\n' ||
        options.lineBreak === '\r\n') {
      this.bestLineBreak = options.lineBreak;
    }

    this.tagPrefixes = null;
    this.preparedAnchor = null;
    this.preparedTag = null;
    this.analysis = null;
    this.style = null;
  }

  // --- Event queue -------------------------------------------------------

  emit(event) {
    this.events.push(event);
    while (!this.needMoreEvents()) {
      this.event = this.events.shift();
      this.state.call(this);
      this.event = null;
    }
  }

  needMoreEvents() {
    if (this.events.length === 0) return true;
    const event = this.events[0];
    if (event.id === 'document-start') return this.needEvents(1);
    if (event.id === 'sequence-start') return this.needEvents(2);
    if (event.id === 'mapping-start') return this.needEvents(3);
    return false;
  }

  needEvents(count) {
    let level = 0;
    for (const event of this.events.slice(1)) {
      if (event.id === 'document-start' || isCollectionStart(event)) level += 1;
      else if (event.id === 'document-end' || event.id === 'sequence-end' ||
        event.id === 'mapping-end') level -= 1;
      else if (event.id === 'stream-end') level = -1;
      if (level < 0) return false;
    }
    return this.events.length < count + 1;
  }

  increaseIndent(flow = false, indentless = false) {
    this.indents.push(this.indent);
    if (this.indent === null) {
      this.indent = flow ? this.bestIndent : 0;
    } else if (!indentless) {
      this.indent += this.bestIndent;
    }
  }

  // --- States: stream and document ---------------------------------------

  expectStreamStart() {
    if (this.event.id === 'stream-start') {
      this.writeStreamStart();
      this.state = this.expectFirstDocumentStart;
    } else {
      throw new EmitterError(`expected StreamStartEvent, but got ${this.event.id}`);
    }
  }

  expectNothing() {
    throw new EmitterError(`expected nothing, but got ${this.event.id}`);
  }

  expectFirstDocumentStart() {
    return this.expectDocumentStart(true);
  }

  expectDocumentStart(first = false) {
    if (this.event.id === 'document-start') {
      if ((this.event.version || this.event.tags) && this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.tagPrefixes = new Map(DEFAULT_TAG_PREFIXES);
      const implicit = first && !this.event.explicit && !this.canonical &&
        !this.event.version && !this.event.tags && !this.checkEmptyDocument();
      if (!implicit) {
        this.writeIndent();
        this.writeIndicator('---', true);
        if (this.canonical) this.writeIndent();
      }
      this.state = this.expectDocumentRoot;
    } else if (this.event.id === 'stream-end') {
      if (this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.writeStreamEnd();
      this.state = this.expectNothing;
    } else {
      throw new EmitterError(`expected DocumentStartEvent, but got ${this.event.id}`);
    }
  }

  expectDocumentEnd() {
    if (this.event.id === 'document-end') {
      this.writeIndent();
      if (this.event.explicit) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.state = this.expectDocumentStart;
    } else {
      throw new EmitterError(`expected DocumentEndEvent, but got ${this.event.id}`);
    }
  }

  expectDocumentRoot() {
    this.states.push(this.expectDocumentEnd);
    this.expectNode(true, false, false, false);
  }

  // --- States: nodes -----------------------------------------------------

  expectNode(root = false, sequence = false, mapping = false, simpleKey = false) {
    this.rootContext = root;
    this.sequenceContext = sequence;
    this.mappingContext = mapping;
    this.simpleKeyContext = simpleKey;
    if (this.event.id === 'alias') {
      this.expectAlias();
    } else if (this.event.id === 'scalar' || isCollectionStart(this.event)) {
      this.processAnchor('&');
      this.processTag();
      if (this.event.id === 'scalar') {
        this.expectScalar();
      } else if (this.event.id === 'sequence-start') {
        if (this.flowLevel || this.canonical || this.event.flowStyle ||
            this.checkEmptySequence()) {
          this.expectFlowSequence();
        } else {
          this.expectBlockSequence();
        }
      } else if (this.event.id === 'mapping-start') {
        if (this.flowLevel || this.canonical || this.event.flowStyle ||
            this.checkEmptyMapping()) {
          this.expectFlowMapping();
        } else {
          this.expectBlockMapping();
        }
      }
    } else {
      throw new EmitterError(`expected NodeEvent, but got ${this.event.id}`);
    }
  }

  expectAlias() {
    if (this.event.anchor === null) {
      throw new EmitterError('anchor is not specified for alias');
    }
    this.processAnchor('*');
    this.state = this.states.pop();
  }

  expectScalar() {
    this.increaseIndent(true);
    this.processScalar();
    this.indent = this.indents.pop();
    this.state = this.states.pop();
  }

  // --- States: flow sequences --------------------------------------------

  expectFlowSequence() {
    this.writeIndicator('[', true, true);
    this.flowLevel += 1;
    this.increaseIndent(true);
    this.state = this.expectFirstFlowSequenceItem;
  }

  expectFirstFlowSequenceItem() {
    if (this.event.id === 'sequence-end') {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator(']', false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push(this.expectFlowSequenceItem);
      this.expectNode(false, true, false, false);
    }
  }

  expectFlowSequenceItem() {
    if (this.event.id === 'sequence-end') {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false);
        this.writeIndent();
      }
      this.writeIndicator(']', false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push(this.expectFlowSequenceItem);
      this.expectNode(false, true, false, false);
    }
  }

  // --- States: flow mappings ---------------------------------------------

  expectFlowMapping() {
    this.writeIndicator('{', true, true);
    this.flowLevel += 1;
    this.increaseIndent(true);
    this.state = this.expectFirstFlowMappingKey;
  }

  expectFirstFlowMappingKey() {
    if (this.event.id === 'mapping-end') {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator('}', false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push(this.expectFlowMappingSimpleValue);
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true);
        this.states.push(this.expectFlowMappingValue);
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectFlowMappingKey() {
    if (this.event.id === 'mapping-end') {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false);
        this.writeIndent();
      }
      this.writeIndicator('}', false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push(this.expectFlowMappingSimpleValue);
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true);
        this.states.push(this.expectFlowMappingValue);
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectFlowMappingSimpleValue() {
    this.writeIndicator(':', false);
    this.states.push(this.expectFlowMappingKey);
    this.expectNode(false, false, true, false);
  }

  expectFlowMappingValue() {
    if (this.canonical || this.column > this.bestWidth) this.writeIndent();
    this.writeIndicator(':', true);
    this.states.push(this.expectFlowMappingKey);
    this.expectNode(false, false, true, false);
  }

  // --- States: block collections -----------------------------------------

  expectBlockSequence() {
    const indentless = this.mappingContext && !this.indention;
    this.increaseIndent(false, indentless);
    this.state = this.expectFirstBlockSequenceItem;
  }

  expectFirstBlockSequenceItem() {
    return this.expectBlockSequenceItem(true);
  }

  expectBlockSequenceItem(first = false) {
    if (!first && this.event.id === 'sequence-end') {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      this.writeIndicator('-', true, false, true);
      this.states.push(this.expectBlockSequenceItemNotFirst);
      this.expectNode(false, true, false, false);
    }
  }

  /** Bound continuation for `expect_block_sequence_item` (first=False). */
  expectBlockSequenceItemNotFirst() {
    return this.expectBlockSequenceItem(false);
  }

  expectBlockMapping() {
    this.increaseIndent(false);
    this.state = this.expectFirstBlockMappingKey;
  }

  expectFirstBlockMappingKey() {
    return this.expectBlockMappingKey(true);
  }

  expectBlockMappingKey(first = false) {
    if (!first && this.event.id === 'mapping-end') {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      if (this.checkSimpleKey()) {
        this.states.push(this.expectBlockMappingSimpleValue);
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true, false, true);
        this.states.push(this.expectBlockMappingValue);
        this.expectNode(false, false, true, false);
      }
    }
  }

  /** Bound continuation for `expect_block_mapping_key` (first=False). */
  expectBlockMappingKeyNotFirst() {
    return this.expectBlockMappingKey(false);
  }

  expectBlockMappingSimpleValue() {
    this.writeIndicator(':', false);
    this.states.push(this.expectBlockMappingKeyNotFirst);
    this.expectNode(false, false, true, false);
  }

  expectBlockMappingValue() {
    this.writeIndent();
    this.writeIndicator(':', true, false, true);
    this.states.push(this.expectBlockMappingKeyNotFirst);
    this.expectNode(false, false, true, false);
  }

  // --- Checkers ----------------------------------------------------------

  checkEmptySequence() {
    return this.event.id === 'sequence-start' && this.events.length > 0 &&
      this.events[0].id === 'sequence-end';
  }

  checkEmptyMapping() {
    return this.event.id === 'mapping-start' && this.events.length > 0 &&
      this.events[0].id === 'mapping-end';
  }

  checkEmptyDocument() {
    if (this.event.id !== 'document-start' || this.events.length === 0) return false;
    const event = this.events[0];
    return event.id === 'scalar' && event.anchor === null && event.tag === null &&
      event.implicit && event.value === '';
  }

  checkSimpleKey() {
    let length = 0;
    if (isNodeEvent(this.event) && this.event.anchor !== null) {
      if (this.preparedAnchor === null) {
        this.preparedAnchor = this.prepareAnchor(this.event.anchor);
      }
      length += this.preparedAnchor.length;
    }
    if ((this.event.id === 'scalar' || isCollectionStart(this.event)) &&
        this.event.tag !== null) {
      if (this.preparedTag === null) this.preparedTag = this.prepareTag(this.event.tag);
      length += this.preparedTag.length;
    }
    if (this.event.id === 'scalar') {
      if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
      length += this.analysis.scalar.length;
    }
    return length < 128 && (this.event.id === 'alias' ||
      (this.event.id === 'scalar' && !this.analysis.empty && !this.analysis.multiline) ||
      this.checkEmptySequence() || this.checkEmptyMapping());
  }

  // --- Anchor, tag and scalar processors ---------------------------------

  processAnchor(indicator) {
    if (this.event.anchor === null) {
      this.preparedAnchor = null;
      return;
    }
    if (this.preparedAnchor === null) {
      this.preparedAnchor = this.prepareAnchor(this.event.anchor);
    }
    if (this.preparedAnchor) this.writeIndicator(indicator + this.preparedAnchor, true);
    this.preparedAnchor = null;
  }

  processTag() {
    let tag = this.event.tag;
    if (this.event.id === 'scalar') {
      if (this.style === null) this.style = this.chooseScalarStyle();
      if ((!this.canonical || tag === null) &&
          ((this.style === '' && this.event.implicit[0]) ||
           (this.style !== '' && this.event.implicit[1]))) {
        this.preparedTag = null;
        return;
      }
      if (this.event.implicit[0] && tag === null) {
        tag = '!';
        this.preparedTag = null;
      }
    } else if ((!this.canonical || tag === null) && this.event.implicit) {
      this.preparedTag = null;
      return;
    }
    if (tag === null) throw new EmitterError('tag is not specified');
    if (this.preparedTag === null) this.preparedTag = this.prepareTag(tag);
    if (this.preparedTag) this.writeIndicator(this.preparedTag, true);
    this.preparedTag = null;
  }

  chooseScalarStyle() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.event.style === '"' || this.canonical) return '"';
    if (!this.event.style && this.event.implicit[0]) {
      if (!(this.simpleKeyContext && (this.analysis.empty || this.analysis.multiline)) &&
          ((this.flowLevel && this.analysis.allowFlowPlain) ||
           (!this.flowLevel && this.analysis.allowBlockPlain))) {
        return '';
      }
    }
    if (this.event.style && inSet(this.event.style, '|>')) {
      if (!this.flowLevel && !this.simpleKeyContext && this.analysis.allowBlock) {
        return this.event.style;
      }
    }
    if (!this.event.style || this.event.style === "'") {
      if (this.analysis.allowSingleQuoted &&
          !(this.simpleKeyContext && this.analysis.multiline)) {
        return "'";
      }
    }
    return '"';
  }

  processScalar() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.style === null) this.style = this.chooseScalarStyle();
    const split = !this.simpleKeyContext;
    if (this.style === '"') this.writeDoubleQuoted(this.analysis.scalar, split);
    else if (this.style === "'") this.writeSingleQuoted(this.analysis.scalar, split);
    else if (this.style === '>') this.writeFolded(this.analysis.scalar);
    else if (this.style === '|') this.writeLiteral(this.analysis.scalar);
    else this.writePlain(this.analysis.scalar, split);
    this.analysis = null;
    this.style = null;
  }

  // --- Analyzers ---------------------------------------------------------

  prepareAnchor(anchor) {
    if (!anchor) throw new EmitterError('anchor must not be empty');
    for (const ch of anchor) {
      const ok = (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') ||
        (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_';
      if (!ok) {
        throw new EmitterError(`invalid character ${pyRepr(ch)} in the anchor: ` +
          `${pyRepr(anchor)}`);
      }
    }
    return anchor;
  }

  prepareTag(tag) {
    if (!tag) throw new EmitterError('tag must not be empty');
    if (tag === '!') return tag;
    let handle = null;
    let suffix = tag;
    const prefixes = Array.from(this.tagPrefixes.keys()).sort();
    for (const prefix of prefixes) {
      if (tag.startsWith(prefix) && (prefix === '!' || prefix.length < tag.length)) {
        handle = this.tagPrefixes.get(prefix);
        suffix = tag.slice(prefix.length);
      }
    }
    const chunks = [];
    let start = 0;
    let end = 0;
    const chars = Array.from(suffix);
    while (end < chars.length) {
      const ch = chars[end];
      const plain = (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') ||
        (ch >= 'a' && ch <= 'z') || inSet(ch, "-;/?:@&=+$,_.~*'()[]") ||
        (ch === '!' && handle !== '!');
      if (plain) {
        end += 1;
      } else {
        if (start < end) chunks.push(chars.slice(start, end).join(''));
        end += 1;
        start = end;
        for (const byte of new TextEncoder().encode(ch)) {
          chunks.push('%' + hexUpper(byte, 2));
        }
      }
    }
    if (start < end) chunks.push(chars.slice(start, end).join(''));
    const suffixText = chunks.join('');
    if (handle) return handle + suffixText;
    return `!<${suffixText}>`;
  }

  analyzeScalar(scalar) {
    if (!scalar) {
      return new ScalarAnalysis(scalar, true, false, false, true, true, true, false);
    }

    const chars = Array.from(scalar);
    const length = chars.length;

    let blockIndicators = false;
    let flowIndicators = false;
    let lineBreaks = false;
    let specialCharacters = false;

    let leadingSpace = false;
    let leadingBreak = false;
    let trailingSpace = false;
    let trailingBreak = false;
    let breakSpace = false;
    let spaceBreak = false;

    if (scalar.startsWith('---') || scalar.startsWith('...')) {
      blockIndicators = true;
      flowIndicators = true;
    }

    let precededByWhitespace = true;
    let followedByWhitespace = length === 1 || inSet(chars[1], NULL_BL_T_LINEBR);
    let previousSpace = false;
    let previousBreak = false;

    let index = 0;
    while (index < length) {
      const ch = chars[index];

      if (index === 0) {
        if (inSet(ch, '#,[]{}&*!|>\'"%@`')) {
          flowIndicators = true;
          blockIndicators = true;
        }
        if (inSet(ch, '?:')) {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '-' && followedByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      } else {
        if (inSet(ch, ',?[]{}')) flowIndicators = true;
        if (ch === ':') {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '#' && precededByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      }

      if (inSet(ch, BREAKS)) lineBreaks = true;
      if (!(ch === '\n' || (ch >= '\x20' && ch <= '\x7E'))) {
        const code = ch.codePointAt(0);
        const knownUnicode = (code === 0x85 || (code >= 0xa0 && code <= 0xd7ff) ||
          (code >= 0xe000 && code <= 0xfffd) ||
          (code >= 0x10000 && code < 0x10ffff)) && code !== 0xfeff;
        if (knownUnicode) {
          if (!this.allowUnicode) specialCharacters = true;
        } else {
          specialCharacters = true;
        }
      }

      if (ch === ' ') {
        if (index === 0) leadingSpace = true;
        if (index === length - 1) trailingSpace = true;
        if (previousBreak) breakSpace = true;
        previousSpace = true;
        previousBreak = false;
      } else if (inSet(ch, BREAKS)) {
        if (index === 0) leadingBreak = true;
        if (index === length - 1) trailingBreak = true;
        if (previousSpace) spaceBreak = true;
        previousSpace = false;
        previousBreak = true;
      } else {
        previousSpace = false;
        previousBreak = false;
      }

      // PyYAML advances the index before recomputing the look-ahead, which
      // makes `followedByWhitespace` peek one character further than the name
      // suggests. Keep the same off-by-one.
      index += 1;
      precededByWhitespace = inSet(ch, NULL_BL_T_LINEBR);
      followedByWhitespace = index + 1 >= length || inSet(chars[index + 1], NULL_BL_T_LINEBR);
    }

    let allowFlowPlain = true;
    let allowBlockPlain = true;
    let allowSingleQuoted = true;
    const allowDoubleQuoted = true;
    let allowBlock = true;

    if (leadingSpace || leadingBreak || trailingSpace || trailingBreak) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (trailingSpace) allowBlock = false;
    if (breakSpace) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
    }
    if (spaceBreak || specialCharacters) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
      allowBlock = false;
    }
    if (lineBreaks) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (flowIndicators) allowFlowPlain = false;
    if (blockIndicators) allowBlockPlain = false;

    return new ScalarAnalysis(scalar, false, lineBreaks, allowFlowPlain, allowBlockPlain,
      allowSingleQuoted, allowDoubleQuoted, allowBlock);
  }

  // --- Writers -----------------------------------------------------------

  writeStreamStart() {
    // No BOM: this emitter always produces text.
  }

  writeStreamEnd() {
    // Nothing to flush.
  }

  write(data) {
    this.stream.write(data);
  }

  writeIndicator(indicator, needWhitespace, whitespace = false, indention = false) {
    const data = (this.whitespace || !needWhitespace) ? indicator : ' ' + indicator;
    this.whitespace = whitespace;
    this.indention = this.indention && indention;
    this.column += data.length;
    this.openEnded = false;
    this.write(data);
  }

  writeIndent() {
    const indent = this.indent || 0;
    if (!this.indention || this.column > indent ||
        (this.column === indent && !this.whitespace)) {
      this.writeLineBreak();
    }
    if (this.column < indent) {
      this.whitespace = true;
      const data = ' '.repeat(indent - this.column);
      this.column = indent;
      this.write(data);
    }
  }

  writeLineBreak(data = null) {
    const text = data === null ? this.bestLineBreak : data;
    this.whitespace = true;
    this.indention = true;
    this.line += 1;
    this.column = 0;
    this.write(text);
  }

  writeSingleQuoted(text, split = true) {
    this.writeIndicator("'", true);
    let spaces = false;
    let breaks = false;
    let start = 0;
    let end = 0;
    const chars = Array.from(text);
    while (end <= chars.length) {
      let ch = null;
      if (end < chars.length) ch = chars[end];
      if (spaces) {
        if (ch === null || ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split &&
              start !== 0 && end !== chars.length) {
            this.writeIndent();
          } else {
            const data = chars.slice(start, end).join('');
            this.column += data.length;
            this.write(data);
          }
          start = end;
        }
      } else if (breaks) {
        if (ch === null || !inSet(ch, BREAKS)) {
          if (chars[start] === '\n') this.writeLineBreak();
          for (const br of chars.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          start = end;
        }
      } else if (ch === null || inSet(ch, ' ' + BREAKS) || ch === "'") {
        if (start < end) {
          const data = chars.slice(start, end).join('');
          this.column += data.length;
          this.write(data);
          start = end;
        }
      }
      if (ch === "'") {
        this.column += 2;
        this.write("''");
        start = end + 1;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = inSet(ch, BREAKS);
      }
      end += 1;
    }
    this.writeIndicator("'", false);
  }

  writeDoubleQuoted(text, split = true) {
    this.writeIndicator('"', true);
    let start = 0;
    let end = 0;
    const chars = Array.from(text);
    while (end <= chars.length) {
      let ch = null;
      if (end < chars.length) ch = chars[end];
      const code = ch === null ? 0 : ch.codePointAt(0);
      const needsEscape = ch !== null && (inSet(ch, '"\\\x85') || code === 0x2028 ||
        code === 0x2029 || code === 0xfeff ||
        !((ch >= '\x20' && ch <= '\x7E') ||
          (this.allowUnicode && ((code >= 0xa0 && code <= 0xd7ff) ||
            (code >= 0xe000 && code <= 0xfffd) ||
            (code >= 0x10000 && code < 0x10ffff)))));
      if (ch === null || needsEscape) {
        if (start < end) {
          const data = chars.slice(start, end).join('');
          this.column += data.length;
          this.write(data);
          start = end;
        }
        if (ch !== null) {
          let data;
          if (ESCAPE_REPLACEMENTS.has(ch)) {
            data = '\\' + ESCAPE_REPLACEMENTS.get(ch);
          } else if (code <= 0xff) {
            data = '\\x' + hexUpper(code, 2);
          } else if (code <= 0xffff) {
            data = '\\u' + hexUpper(code, 4);
          } else {
            data = '\\U' + hexUpper(code, 8);
          }
          this.column += data.length;
          this.write(data);
          start = end + 1;
        }
      }
      if (end > 0 && end < chars.length - 1 && (ch === ' ' || start >= end) &&
          this.column + (end - start) > this.bestWidth && split) {
        const data = chars.slice(start, end).join('') + '\\';
        if (start < end) start = end;
        this.column += data.length;
        this.write(data);
        this.writeIndent();
        this.whitespace = false;
        this.indention = false;
        if (chars[start] === ' ') {
          this.column += 1;
          this.write('\\');
        }
      }
      end += 1;
    }
    this.writeIndicator('"', false);
  }

  determineBlockHints(text) {
    let hints = '';
    if (text) {
      const chars = Array.from(text);
      if (inSet(chars[0], SPACE_AND_BREAKS)) hints += String(this.bestIndent);
      const last = chars[chars.length - 1];
      if (!inSet(last, BREAKS)) hints += '-';
      else if (chars.length === 1 || inSet(chars[chars.length - 2], BREAKS)) hints += '+';
    }
    return hints;
  }

  writeFolded(text) {
    const hints = this.determineBlockHints(text);
    this.writeIndicator('>' + hints, true);
    if (hints.endsWith('+')) this.openEnded = true;
    this.writeLineBreak();
    let leadingSpace = true;
    let spaces = false;
    let breaks = true;
    let start = 0;
    let end = 0;
    const chars = Array.from(text);
    while (end <= chars.length) {
      let ch = null;
      if (end < chars.length) ch = chars[end];
      if (breaks) {
        if (ch === null || !inSet(ch, BREAKS)) {
          if (!leadingSpace && ch !== null && ch !== ' ' && chars[start] === '\n') {
            this.writeLineBreak();
          }
          leadingSpace = ch === ' ';
          for (const br of chars.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth) {
            this.writeIndent();
          } else {
            const data = chars.slice(start, end).join('');
            this.column += data.length;
            this.write(data);
          }
          start = end;
        }
      } else if (ch === null || inSet(ch, ' ' + BREAKS)) {
        const data = chars.slice(start, end).join('');
        this.column += data.length;
        this.write(data);
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) {
        breaks = inSet(ch, BREAKS);
        spaces = ch === ' ';
      }
      end += 1;
    }
  }

  writeLiteral(text) {
    const hints = this.determineBlockHints(text);
    this.writeIndicator('|' + hints, true);
    if (hints.endsWith('+')) this.openEnded = true;
    this.writeLineBreak();
    let breaks = true;
    let start = 0;
    let end = 0;
    const chars = Array.from(text);
    while (end <= chars.length) {
      let ch = null;
      if (end < chars.length) ch = chars[end];
      if (breaks) {
        if (ch === null || !inSet(ch, BREAKS)) {
          for (const br of chars.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (ch === null || inSet(ch, BREAKS)) {
        const data = chars.slice(start, end).join('');
        this.write(data);
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) breaks = inSet(ch, BREAKS);
      end += 1;
    }
  }

  writePlain(text, split = true) {
    if (this.rootContext) this.openEnded = true;
    if (!text) return;
    if (!this.whitespace) {
      this.column += 1;
      this.write(' ');
    }
    this.whitespace = false;
    this.indention = false;
    let spaces = false;
    let breaks = false;
    let start = 0;
    let end = 0;
    const chars = Array.from(text);
    while (end <= chars.length) {
      let ch = null;
      if (end < chars.length) ch = chars[end];
      if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split) {
            this.writeIndent();
            this.whitespace = false;
            this.indention = false;
          } else {
            const data = chars.slice(start, end).join('');
            this.column += data.length;
            this.write(data);
          }
          start = end;
        }
      } else if (breaks) {
        if (ch === null || !inSet(ch, BREAKS)) {
          if (chars[start] === '\n') this.writeLineBreak();
          for (const br of chars.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          this.whitespace = false;
          this.indention = false;
          start = end;
        }
      } else if (ch === null || inSet(ch, ' ' + BREAKS)) {
        const data = chars.slice(start, end).join('');
        this.column += data.length;
        this.write(data);
        start = end;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = inSet(ch, BREAKS);
      }
      end += 1;
    }
  }
}

