/**
 * Node → event serialization — a port of PyYAML's `yaml/serializer.py`.
 *
 * Nodes reachable more than once get an `&id00N` anchor and are re-emitted as
 * aliases, exactly like Python (node identity decides, not equality).
 */

import { SerializerError } from './errors.mjs';
import { ScalarNode, SequenceNode, MappingNode, SCALAR, SEQUENCE, MAPPING } from './nodes.mjs';
import {
  StreamStartEvent, StreamEndEvent, DocumentStartEvent, DocumentEndEvent,
  AliasEvent, ScalarEvent, SequenceStartEvent, SequenceEndEvent,
  MappingStartEvent, MappingEndEvent,
} from './events.mjs';

export class Serializer {
  constructor(emitter, resolver, options = {}) {
    this.emitter = emitter;
    this.resolver = resolver;
    this.useEncoding = options.encoding === undefined ? null : options.encoding;
    this.useExplicitStart = options.explicitStart === undefined ? null : options.explicitStart;
    this.useExplicitEnd = options.explicitEnd === undefined ? null : options.explicitEnd;
    this.useVersion = options.version === undefined ? null : options.version;
    this.useTags = options.tags === undefined ? null : options.tags;
    this.serializedNodes = new Set();
    this.anchors = new Map();
    this.lastAnchorId = 0;
    this.closed = null;
  }

  open() {
    if (this.closed === null) {
      this.emitter.emit(new StreamStartEvent(null, null, this.useEncoding));
      this.closed = false;
    } else if (this.closed) {
      throw new SerializerError('serializer is closed');
    } else {
      throw new SerializerError('serializer is already opened');
    }
