/**
 * Value → node representation — a port of PyYAML's `SafeRepresenter` plus the
 * `!!python/tuple` handling that plain `yaml.dump` inherits from `Representer`.
 *
 * Mapping keys are sorted with Python's `sorted()` semantics: any incomparable
 * pair (str vs int, None vs anything, …) aborts the sort and the original
 * insertion order is kept.
 */

import { RepresenterError } from './errors.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
import { floatRepr } from './pynumber.mjs';
import {
  PyDate, PyDateTime, PyBytes, PyTuple, PyDict, PySet, PyTypeError, pySorted,
} from './pytypes.mjs';

const BASE64_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** `base64.encodebytes`: standard base64 wrapped at 76 characters per line. */
function encodeBase64Lines(bytes) {
  let encoded = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    encoded += BASE64_ALPHABET[b0 >> 2];
    encoded += BASE64_ALPHABET[((b0 & 0x03) << 4) | (b1 >> 4)];
    encoded += i + 1 < bytes.length ? BASE64_ALPHABET[((b1 & 0x0f) << 2) | (b2 >> 6)] : '=';
    encoded += i + 2 < bytes.length ? BASE64_ALPHABET[b2 & 0x3f] : '=';
  }
  let out = '';
  for (let i = 0; i < encoded.length; i += 76) {
    out += encoded.slice(i, i + 76) + '\n';
  }
  return out;
}

export class Representer {
  constructor(serializer, options = {}) {
    this.serializer = serializer;
    this.defaultStyle = options.defaultStyle === undefined ? null : options.defaultStyle;
    this.defaultFlowStyle = options.defaultFlowStyle === undefined
      ? false : options.defaultFlowStyle;
    this.sortKeys = options.sortKeys === undefined ? true : options.sortKeys;
    this.representedObjects = new Map();
    this.aliasKey = null;
  }

  represent(data) {
    const node = this.representData(data);
    this.serializer.serialize(node);
    this.representedObjects = new Map();
    this.aliasKey = null;
  }

  /** Immutable scalars are never aliased (SafeRepresenter.ignore_aliases). */
  ignoreAliases(data) {
    if (data === null) return true;
    if (data instanceof PyTuple && data.items.length === 0) return true;
    if (data instanceof PyBytes) return true;
    const type = typeof data;
    return type === 'string' || type === 'boolean' || type === 'bigint' || type === 'number';
  }

  representData(data) {
    this.aliasKey = this.ignoreAliases(data) ? null : data;
    if (this.aliasKey !== null && this.representedObjects.has(this.aliasKey)) {
      return this.representedObjects.get(this.aliasKey);
    }
    if (data === null) return this.representNone();
    switch (typeof data) {
      case 'string':
        return this.representStr(data);
      case 'boolean':
        return this.representBool(data);
      case 'bigint':
        return this.representInt(data);
      case 'number':
        return this.representFloat(data);
      default:
        break;
    }
    if (Array.isArray(data)) return this.representList(data);
    if (data instanceof PyDict) return this.representDict(data);
    if (data instanceof PySet) return this.representSet(data);
    if (data instanceof PyDateTime) return this.representDatetime(data);
    if (data instanceof PyDate) return this.representDate(data);
    if (data instanceof PyBytes) return this.representBinary(data);
    if (data instanceof PyTuple) return this.representTuple(data);
