  }

  // --- Building blocks ---------------------------------------------------

  representScalar(tag, value, style = null) {
    const useStyle = style === null ? this.defaultStyle : style;
    const node = new ScalarNode(tag, value, null, null, useStyle);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    return node;
  }

  representSequence(tag, sequence, flowStyle = null) {
    const value = [];
    const node = new SequenceNode(tag, value, null, null, flowStyle);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    let bestStyle = true;
    for (const item of sequence) {
      const nodeItem = this.representData(item);
      if (!(nodeItem instanceof ScalarNode && !nodeItem.style)) bestStyle = false;
      value.push(nodeItem);
    }
    if (flowStyle === null) {
      node.flowStyle = this.defaultFlowStyle === null ? bestStyle : this.defaultFlowStyle;
    }
    return node;
  }

  representMapping(tag, mapping, flowStyle = null) {
    const value = [];
    const node = new MappingNode(tag, value, null, null, flowStyle);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    let bestStyle = true;
    let items = mapping.items();
    if (this.sortKeys) {
      try {
        items = pySorted(items);
      } catch (err) {
        if (!(err instanceof PyTypeError)) throw err;
        // Python swallows TypeError and keeps the insertion order.
      }
    }
    for (const [itemKey, itemValue] of items) {
      const nodeKey = this.representData(itemKey);
      const nodeValue = this.representData(itemValue);
      if (!(nodeKey instanceof ScalarNode && !nodeKey.style)) bestStyle = false;
      if (!(nodeValue instanceof ScalarNode && !nodeValue.style)) bestStyle = false;
      value.push([nodeKey, nodeValue]);
    }
    if (flowStyle === null) {
      node.flowStyle = this.defaultFlowStyle === null ? bestStyle : this.defaultFlowStyle;
    }
    return node;
  }

  // --- Type specific representers ----------------------------------------

  representNone() {
    return this.representScalar('tag:yaml.org,2002:null', 'null');
  }

  representStr(data) {
    return this.representScalar('tag:yaml.org,2002:str', data);
  }

  representBool(data) {
    return this.representScalar('tag:yaml.org,2002:bool', data ? 'true' : 'false');
  }

  representInt(data) {
    return this.representScalar('tag:yaml.org,2002:int', data.toString());
  }

  representFloat(data) {
    let value;
    if (Number.isNaN(data)) {
      value = '.nan';
    } else if (data === Infinity) {
      value = '.inf';
    } else if (data === -Infinity) {
      value = '-.inf';
    } else {
      value = floatRepr(data).toLowerCase();
      // '!!float' requires a decimal part, so 1e+17 becomes 1.0e+17.
      if (!value.includes('.') && value.includes('e')) value = value.replace('e', '.0e');
    }
    return this.representScalar('tag:yaml.org,2002:float', value);
  }

  representList(data) {
    return this.representSequence('tag:yaml.org,2002:seq', data);
  }

  representTuple(data) {
    return this.representSequence('tag:yaml.org,2002:python/tuple', data.items);
  }

  representDict(data) {
    return this.representMapping('tag:yaml.org,2002:map', data);
  }

  representSet(data) {
    const value = new PyDict();
    for (const key of data.values()) value.set(key, null);
    return this.representMapping('tag:yaml.org,2002:set', value);
  }

  representDate(data) {
    return this.representScalar('tag:yaml.org,2002:timestamp', data.isoformat());
  }

  representDatetime(data) {
    return this.representScalar('tag:yaml.org,2002:timestamp', data.isoformat(' '));
  }

  representBinary(data) {
    return this.representScalar('tag:yaml.org,2002:binary',
      encodeBase64Lines(data.data), '|');
  }
}

