/** Collects emitted text, standing in for Python's `io.StringIO`. */
class StringStream {
  constructor() {
    this.chunks = [];
  }

  write(data) {
    this.chunks.push(data);
  }

  getvalue() {
    return this.chunks.join('');
  }
}

/**
 * `yaml.safe_load(text)` — parse a single document into Python-like values.
 * Integers become `bigint`, floats `number`, mappings `PyDict`, and so on.
 */
export function safeLoad(text, name = '<unicode string>') {
  const loader = new SafeConstructor(text, name);
  return loader.getSingleData();
}

/**
 * `yaml.dump(data, **options)` — serialize one document to a string.
 *
 * Defaults match PyYAML: block style, indent 2, best width 80, ASCII only.
 */
export function dump(data, options = {}) {
  const stream = new StringStream();
  const emitter = new Emitter(stream, {
    canonical: options.canonical,
    indent: options.indent,
    width: options.width,
    allowUnicode: options.allowUnicode,
    lineBreak: options.lineBreak,
  });
  const resolver = new Resolver();
  const serializer = new Serializer(emitter, resolver, {
    explicitStart: options.explicitStart,
    explicitEnd: options.explicitEnd,
    version: options.version,
    tags: options.tags,
  });
  const representer = new Representer(serializer, {
    defaultStyle: options.defaultStyle,
    defaultFlowStyle: options.defaultFlowStyle === undefined ? false : options.defaultFlowStyle,
    sortKeys: options.sortKeys,
  });
  serializer.open();
  representer.represent(data);
  serializer.close();
  return stream.getvalue();
}

