/**
 * Minimal `argparse` port covering the behaviour this script relies on:
 * a required `--a VALUE` option plus the automatic `-h/--help`.
 *
 * The subtle part is Python's classification of each argv entry as an option
 * ('O') or a value ('A'): a value starting with '-' is only accepted when it
 * looks like a negative number or contains a space. `--a -abc` therefore fails
 * with "expected one argument", exactly as CPython does.
 */

const MAX_HELP_POSITION = 24;
const INDENT = 2;

/** Python's `_negative_number_matcher`: ^-\d+$|^-\d*\.\d+$ */
function looksLikeNegativeNumber(text) {
  if (text[0] !== '-' || text.length < 2) return false;
  const rest = text.slice(1);
  const digits = (s) => s.length > 0 && Array.from(s).every((ch) => ch >= '0' && ch <= '9');
  if (digits(rest)) return true;
  const dot = rest.indexOf('.');
  if (dot === -1) return false;
  const head = rest.slice(0, dot);
  const tail = rest.slice(dot + 1);
  const headOk = head.length === 0 || digits(head);
  return headOk && digits(tail);
}

class Action {
  constructor(optionStrings, dest, { required = false, nargs = null, help = null } = {}) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.required = required;
    this.nargs = nargs; // null => exactly one argument, 0 => flag
    this.help = help;
  }

  /** e.g. "-h, --help" or "--a A" */
  formatInvocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    const metavar = this.dest.toUpperCase();
    return this.optionStrings.map((flag) => `${flag} ${metavar}`).join(', ');
  }

  /** e.g. "[-h]" or "--a A" */
  formatUsage() {
    const flag = this.optionStrings[0];
    const part = this.nargs === 0 ? flag : `${flag} ${this.dest.toUpperCase()}`;
    return this.required ? part : `[${part}]`;
  }
}

/** Raised internally to unwind to `parseArgs`, which reports and exits. */
class ArgumentParserError extends Error {}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog === undefined ? 'prog' : prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.addArgument(['-h', '--help'], {
      nargs: 0,
      dest: 'help',
      help: 'show this help message and exit',
    });
  }

  addArgument(flags, options = {}) {
    const dest = options.dest !== undefined ? options.dest
      : flags[flags.length - 1].replace(/^-+/u, '');
    const action = new Action(flags, dest, options);
    this.actions.push(action);
    for (const flag of flags) this.optionStringActions.set(flag, action);
    return action;
  }

  formatUsage() {
    const parts = this.actions.map((action) => action.formatUsage());
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) => action.formatInvocation());
    const maxLength = Math.max(...invocations.map((text) => text.length + INDENT));
    const helpPosition = Math.min(maxLength + 2, MAX_HELP_POSITION);
    let out = this.formatUsage() + '\noptions:\n';
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      if (action.help === null) {
        out += ' '.repeat(INDENT) + invocation + '\n';
      } else {
        const start = ' '.repeat(INDENT) + invocation;
        const padding = Math.max(helpPosition - start.length, 1);
        out += start + ' '.repeat(padding) + action.help + '\n';
      }
    });
    return out;
  }

  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** Resolve an argv entry to an action, mirroring `_parse_optional`. */
  parseOptional(argString) {
    if (argString.length === 0) return null;
    if (argString[0] !== '-') return null;
    if (this.optionStringActions.has(argString)) {
      return { action: this.optionStringActions.get(argString), optionString: argString,
        explicitArg: null };
    }
    if (argString.length === 1) return null;
    if (argString.includes('=')) {
      const index = argString.indexOf('=');
      const optionString = argString.slice(0, index);
      if (this.optionStringActions.has(optionString)) {
        return { action: this.optionStringActions.get(optionString), optionString,
          explicitArg: argString.slice(index + 1) };
      }
    }
    const tuples = this.getOptionTuples(argString);
    if (tuples.length > 1) {
      const options = tuples.map((tuple) => tuple.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (tuples.length === 1) return tuples[0];
    if (looksLikeNegativeNumber(argString)) return null;
    if (argString.includes(' ')) return null;
    return { action: null, optionString: argString, explicitArg: null };
  }

  /** Abbreviation matching, mirroring `_get_option_tuples`. */
  getOptionTuples(argString) {
    const result = [];
    if (argString.startsWith('--')) {
      let prefix = argString;
      let explicitArg = null;
      if (argString.includes('=')) {
        const index = argString.indexOf('=');
        prefix = argString.slice(0, index);
        explicitArg = argString.slice(index + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) result.push({ action, optionString, explicitArg });
      }
    } else {
      const shortPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortPrefix) {
          result.push({ action, optionString, explicitArg: shortExplicitArg });
        } else if (optionString.startsWith(argString)) {
          result.push({ action, optionString, explicitArg: null });
        }
      }
    }
    return result;
  }

