   * @param {string[]} argv arguments after the script name
   * @returns {object} namespace of parsed values
   */
  parseArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.dest !== 'help') namespace[action.dest] = null;
    }

    // Classify every entry first, like argparse's option_string_indices pass.
    const patterns = [];
    const optionTuples = new Map();
    let afterSeparator = false;
    argv.forEach((argString, index) => {
      if (afterSeparator) {
        patterns.push('A');
        return;
      }
      if (argString === '--') {
        patterns.push('-');
        afterSeparator = true;
        return;
      }
      const tuple = this.parseOptional(argString);
      if (tuple === null) {
        patterns.push('A');
      } else {
        optionTuples.set(index, tuple);
        patterns.push('O');
      }
    });

    const extras = [];
    const seen = new Set();
    let index = 0;
    while (index < argv.length) {
      if (patterns[index] === 'O') {
        const { action, optionString, explicitArg } = optionTuples.get(index);
        if (action === null) {
          extras.push(argv[index]);
          index += 1;
          continue;
        }
        if (action.nargs === 0) {
          if (explicitArg !== null) {
            this.error(`argument ${optionString}: ignored explicit argument ` +
              `'${explicitArg}'`);
          }
          if (action.dest === 'help') {
            process.stdout.write(this.formatHelp());
            process.exit(0);
          }
          seen.add(action);
          index += 1;
          continue;
        }
        if (explicitArg !== null) {
          namespace[action.dest] = explicitArg;
          seen.add(action);
          index += 1;
          continue;
        }
        if (index + 1 < argv.length && patterns[index + 1] === 'A') {
          namespace[action.dest] = argv[index + 1];
          seen.add(action);
          index += 2;
          continue;
        }
        this.error(`argument ${optionString}: expected one argument`);
      } else if (patterns[index] === '-') {
        index += 1; // the '--' separator itself is discarded
      } else {
        extras.push(argv[index]);
        index += 1;
      }
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

