/**
 * CPython-style crash reporting.
 *
 * When `yaml.safe_load` raises, the Python script dies with a traceback on
 * stderr and exit status 1. This module reproduces that shape: the offending
 * source line, then `module.ClassName: message` with the error's own multi-line
 * body (context/problem marks).
 */

import { YAMLError } from '../errors.mjs';

/**
 * Print a traceback for `error` and exit with status 1.
 *
 * @param {Error} error      the raised error
 * @param {string} fileName  script name shown in the traceback
 * @param {number} lineNo    line number of the failing statement
 * @param {string} source    source text of the failing statement
 * @param {string} caret     caret marker aligned under the failing expression
 */
export function reportFatal(error, { fileName, lineNo, source, caret }) {
  const lines = ['Traceback (most recent call last):'];
  lines.push(`  File "${fileName}", line ${lineNo}, in <module>`);
  lines.push(`    ${source}`);
  if (caret) lines.push(`    ${caret}`);
  const name = error instanceof YAMLError ? error.name : pythonName(error);
  const body = error instanceof YAMLError ? error.toString() : error.message;
  lines.push(body ? `${name}: ${body}` : name);
  process.stderr.write(lines.join('\n') + '\n');
  process.exit(1);
}

function pythonName(error) {
  return error && error.name ? error.name : 'Exception';
}

