#!/usr/bin/env node
/**
 * Node port of `test9.py`:
 *
 *     result = yaml.dump(yaml.safe_load(args.a), explicit_start=True)
 *     print(result)
 *
 * Usage: node test9.mjs --a '<yaml document>'
 */

import path from 'node:path';
import { ArgumentParser } from './lib/cli/argparse.mjs';
import { reportFatal } from './lib/cli/traceback.mjs';
import { safeLoad, dump } from './lib/yaml.mjs';

const SOURCE_LINE = 'result = yaml.dump(yaml.safe_load(args.a), explicit_start=True)  # 显式开始';
const SOURCE_CARET = '                   ^^^^^^^^^^^^^^^^^^^^^^';

function main() {
  const prog = path.basename(process.argv[1] || 'test9.mjs');
  const parser = new ArgumentParser({ prog });
  parser.addArgument(['--a'], { required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  let result;
  try {
    result = dump(safeLoad(args.a), { explicitStart: true });
  } catch (error) {
    reportFatal(error, {
      fileName: 'test9.py', lineNo: 8, source: SOURCE_LINE, caret: SOURCE_CARET,
    });
    return;
  }
  // Python's print() appends a newline to the dump, which already ends in one.
  process.stdout.write(result + '\n');
}

main();

