import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test9_executable';
const NODE_ENTRY = '/output/test9.mjs';

export function show(text) {
  let out = '';
  for (const ch of text) {
    const code = ch.codePointAt(0);
    if (ch === '\n') out += '\\n';
    else if (ch === '\t') out += '\\t';
    else if (ch === '\r') out += '\\r';
    else if (code < 0x20 || code === 0x7f) out += '\\x' + code.toString(16).padStart(2, '0');
    else out += ch;
  }
  return out;
}

export function runBoth(arg) {
  const py = spawnSync(EXE, ['--a', arg], { encoding: 'utf8' });
  const js = spawnSync('node', [NODE_ENTRY, '--a', arg], { encoding: 'utf8' });
  return { py, js };
}

export function compare(arg, { verbose = false } = {}) {
  const { py, js } = runBoth(arg);
  const okOut = py.stdout === js.stdout;
  const okCode = py.status === js.status;
  if (okOut && okCode) return { ok: true };
  if (verbose) {
    console.log('--- INPUT: ' + show(arg));
    console.log('  py rc=' + py.status + ' out=' + show(py.stdout));
    console.log('  js rc=' + js.status + ' out=' + show(js.stdout));
    if (!okCode) {
      console.log('  py err=' + show((py.stderr || '').split('\n').slice(-4).join('\n')));
      console.log('  js err=' + show((js.stderr || '').split('\n').slice(-4).join('\n')));
    }
  }
  return { ok: false, py, js };
}

export function runSuite(cases, { verbose = true } = {}) {
  let pass = 0;
  const failures = [];
  for (const arg of cases) {
    const result = compare(arg, { verbose });
    if (result.ok) pass += 1;
    else failures.push(arg);
  }
  console.log(`passed ${pass}/${cases.length}`);
  return failures;
}

