import { runSuite } from './harness.mjs';

// Deterministic PRNG so failures are reproducible.
let seed = Number(process.argv[2] || 12345);
function rand() {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff;
}
function pick(items) {
  return items[Math.floor(rand() * items.length)];
}
function randInt(n) {
  return Math.floor(rand() * n);
}

const CHARS = [
  'a', 'b', 'Z', '0', '9', ' ', '  ', '\n', '\n\n', '\t', ':', ': ', '#', ' #', '-', '- ',
  '?', ',', '[', ']', '{', '}', '&', '*', '!', '|', '>', "'", '"', '%', '@', '`', '\\',
  '.', '~', '=', '<<', 'é', '日', '😀', '\x00', '\x85', '\xa0', ' ', ' ', '\r',
  'word', 'longerword', '---', '...', 'true', 'null', '123', '1.5', 'x'.repeat(15),
];

function randomString() {
  const parts = [];
  const count = randInt(14);
  for (let i = 0; i < count; i += 1) parts.push(pick(CHARS));
  return parts.join('');
}

/** Encode any string as a YAML double-quoted scalar. */
function doubleQuoted(text) {
  let out = '"';
  for (const ch of text) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === '"') out += '\\"';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f) out += '\\x' + code.toString(16).padStart(2, '0');
    else if (code === 0x85 || code === 0xa0) out += '\\x' + code.toString(16).padStart(2, '0');
    else if (code === 0x2028) out += '\\L';
    else if (code === 0x2029) out += '\\P';
    else if (code > 0xffff) out += '\\U' + code.toString(16).padStart(8, '0');
    else if (code > 0x7e) out += '\\u' + code.toString(16).padStart(4, '0');
    else out += ch;
  }
  return out + '"';
}

/** Wrap a quoted scalar in a random document context. */
function contextualize(scalar) {
  const shape = randInt(9);
  switch (shape) {
    case 0: return scalar;
    case 1: return 'k: ' + scalar;
    case 2: return '- ' + scalar;
    case 3: return 'a:\n  b: ' + scalar;
    case 4: return '[' + scalar + ', 1]';
    case 5: return '{k: ' + scalar + '}';
    case 6: return '? ' + scalar + '\n: v';
    case 7: return scalar + ': v';
    case 8: return 'a:\n- b: ' + scalar + '\n  c: [1, ' + scalar + ']';
    default: return scalar;
  }
}

const cases = [];
const total = Number(process.argv[3] || 300);
for (let i = 0; i < total; i += 1) {
  cases.push(contextualize(doubleQuoted(randomString())));
}

const failures = runSuite(cases);
if (failures.length > 0) {
  console.log('FAILING INPUTS:');
  for (const arg of failures.slice(0, 10)) {
    console.log(Array.from(arg).map((c) => {
      const n = c.codePointAt(0);
      return n < 0x20 || n > 0x7e ? '\\u' + n.toString(16).padStart(4, '0') : c;
    }).join(''));
  }
}
